import { useCallback, useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { HiOutlineEye, HiOutlineEyeOff, HiOutlineLockClosed, HiOutlineMail } from 'react-icons/hi';
import { FcGoogle } from 'react-icons/fc';
import { useAuth } from '../../contexts/AuthContext';
import { useStoreSettings } from '../../contexts/StoreSettingsContext';
import { getImageUrl } from '../../utils/imageUrl';
import Modal from '../common/Modal';

export default function LoginModal({ isOpen, onClose }) {
  const { login, loginWithGoogle, onLoginSuccess, closeLoginModal } = useAuth();
  const { settings } = useStoreSettings();
  const navigate = useNavigate();

  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [googleLoading, setGoogleLoading] = useState(false);
  const [googleReady, setGoogleReady] = useState(false);
  const googleButtonRef = useRef(null);
  const googleInitializedRef = useRef(false);

  const authBannerUrl = getImageUrl(settings?.loginModalImage?.url);

  const handleClose = useCallback(() => {
    setErrorMessage('');
    if (onClose) onClose();
    else closeLoginModal();
  }, [onClose, closeLoginModal]);

  const handleSuccess = useCallback(
    (userData) => {
      toast.success(
        `Welcome back${userData?.profile?.firstName ? `, ${userData.profile.firstName}` : ''}!`,
        {
          icon: '✨',
          style: {
            background: '#22201e',
            color: '#f5f0eb',
            border: '1px solid rgba(198, 145, 60, 0.4)',
          },
        }
      );
      setIdentifier('');
      setPassword('');
      setErrorMessage('');
      closeLoginModal();
      if (onClose) onClose();
      onLoginSuccess(userData);
    },
    [onLoginSuccess, onClose, closeLoginModal]
  );

  // Setup Google Sign-In SDK
  useEffect(() => {
    if (!isOpen) return undefined;
    const clientId = import.meta.env.VITE_GOOGLE_CLIENT_ID;
    if (!clientId || !googleButtonRef.current) return undefined;

    const renderGoogleButton = () => {
      if (!window.google?.accounts?.id || !googleButtonRef.current) return;
      try {
        if (!googleInitializedRef.current) {
          window.google.accounts.id.initialize({
            client_id: clientId,
            callback: async ({ credential }) => {
              setGoogleLoading(true);
              try {
                const data = await loginWithGoogle(credential);
                handleSuccess(data.user);
              } catch (error) {
                toast.error(error.response?.data?.message || 'Google sign-in failed');
              } finally {
                setGoogleLoading(false);
              }
            },
          });
          googleInitializedRef.current = true;
        }

        window.google.accounts.id.renderButton(googleButtonRef.current, {
          theme: 'outline',
          size: 'large',
          shape: 'rectangular',
          text: 'continue_with',
          width: Math.max(220, Math.floor(googleButtonRef.current.clientWidth || 320)),
        });
        setTimeout(() => {
          if (
            googleButtonRef.current &&
            (googleButtonRef.current.querySelector('iframe') ||
              googleButtonRef.current.children.length > 0)
          ) {
            setGoogleReady(true);
          }
        }, 200);
      } catch (err) {
        console.warn('Google Sign-in failed to render button:', err);
      }
    };

    let script = document.querySelector('script[src="https://accounts.google.com/gsi/client"]');
    if (!script) {
      script = document.createElement('script');
      script.src = 'https://accounts.google.com/gsi/client';
      script.async = true;
      script.defer = true;
      document.head.appendChild(script);
    }
    script.addEventListener('load', renderGoogleButton);
    renderGoogleButton();
    return () => script.removeEventListener('load', renderGoogleButton);
  }, [isOpen, handleSuccess, loginWithGoogle]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    if (!identifier.trim() || !password) return;
    setLoading(true);
    setErrorMessage('');
    try {
      const data = await login(identifier.trim(), password);
      handleSuccess(data.user);
    } catch (error) {
      const msg = error.response?.data?.message || 'Invalid email/mobile number or password';
      setErrorMessage(msg);
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <Modal open={isOpen} onClose={handleClose} label="Sign in to your Neirah account" className="p-0 border-0 bg-transparent shadow-none">
      <div className="relative grid max-h-[calc(100dvh-2rem)] w-[min(860px,calc(100vw-2rem))] overflow-hidden rounded-3xl bg-white shadow-2xl border border-stone-100 md:grid-cols-[1.1fr_0.9fr]">
        {/* Close Button */}
        <button
          type="button"
          onClick={handleClose}
          aria-label="Close sign in"
          className="absolute right-4 top-4 z-30 flex h-8 w-8 items-center justify-center rounded-full bg-stone-100 text-stone-600 shadow-xs transition hover:bg-stone-200 hover:text-stone-900 md:right-5 md:top-5 md:bg-white/90 md:text-stone-700 md:backdrop-blur-xs md:hover:bg-white cursor-pointer"
        >
          <span aria-hidden="true" className="text-xl leading-none">×</span>
        </button>

        {/* Left Column: Form Section */}
        <section className="flex flex-col justify-center px-6 py-8 sm:px-10 sm:py-10 overflow-y-auto">
          <div>
            <h1 className="font-serif text-[26px] sm:text-[28px] font-bold tracking-tight text-[#4A3525] leading-tight">
              Welcome Back
            </h1>
            <p className="mt-1.5 text-xs sm:text-[13px] text-[#6B635B] font-normal">
              Sign in to access your wishlist, cart & orders.
            </p>
          </div>

          <div className="relative mt-5">
            <button
              type="button"
              onClick={() => {
                try {
                  if (window.google?.accounts?.id && import.meta.env.VITE_GOOGLE_CLIENT_ID) {
                    window.google.accounts.id.prompt();
                  }
                } catch (err) {
                  console.warn('Google sign-in prompt error:', err);
                }
              }}
              className="flex h-11 sm:h-12 w-full items-center justify-center gap-3 rounded-xl border border-stone-200/90 bg-white px-4 text-xs sm:text-[13.5px] font-medium text-stone-700 shadow-2xs hover:bg-stone-50 transition-colors cursor-pointer"
            >
              <FcGoogle className="h-5 w-5 shrink-0" />
              <span>Continue with Google</span>
            </button>
            <div
              ref={googleButtonRef}
              className={`absolute inset-0 opacity-0 overflow-hidden cursor-pointer flex items-center justify-center [&>div]:scale-x-125 [&_iframe]:scale-x-125 ${googleReady ? '' : 'pointer-events-none'}`}
              aria-label="Sign in with Google"
            />
          </div>
          {googleLoading && <p className="mt-1.5 text-center text-xs text-stone-500">Signing in with Google…</p>}

          <div className="my-4 sm:my-5 flex items-center gap-3 text-[11px] font-semibold uppercase tracking-wider text-stone-400">
            <span className="h-px flex-1 bg-stone-200" />
            <span>OR</span>
            <span className="h-px flex-1 bg-stone-200" />
          </div>

          <form onSubmit={handleSubmit} className="space-y-3">
            {errorMessage && (
              <div className="rounded-xl border border-red-200 bg-red-50/90 px-3.5 py-2.5 text-xs text-red-700 flex items-center gap-2">
                <span className="w-1.5 h-1.5 rounded-full bg-red-500 shrink-0" />
                <span className="flex-1 font-medium">{errorMessage}</span>
              </div>
            )}
            <label className="sr-only" htmlFor="modal-login-identifier">Mobile number or email</label>
            <div className="relative">
              <HiOutlineMail className="pointer-events-none absolute left-3.5 top-1/2 h-5 w-5 -translate-y-1/2 text-stone-600" />
              <input
                id="modal-login-identifier"
                type="text"
                autoComplete="username"
                inputMode={identifier.includes('@') ? 'email' : 'tel'}
                value={identifier}
                onChange={(event) => setIdentifier(event.target.value)}
                placeholder="Email or Mobile Number"
                className="h-11 sm:h-12 w-full rounded-xl border border-stone-200/90 bg-[#F8F7F5] pl-11 pr-3 text-sm text-stone-800 outline-none transition placeholder:text-stone-400 focus:border-[#7A5B3E] focus:bg-white focus:ring-2 focus:ring-[#7A5B3E]/15 autofill-neutral"
                required
              />
            </div>

            <label className="sr-only" htmlFor="modal-login-password">Password</label>
            <div className="relative">
              <HiOutlineLockClosed className="pointer-events-none absolute left-3.5 top-1/2 h-5 w-5 -translate-y-1/2 text-stone-600" />
              <input
                id="modal-login-password"
                type={showPassword ? 'text' : 'password'}
                autoComplete="current-password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                placeholder="Password"
                className="h-11 sm:h-12 w-full rounded-xl border border-stone-200/90 bg-[#F8F7F5] pl-11 pr-11 text-sm text-stone-800 outline-none transition placeholder:text-stone-400 focus:border-[#7A5B3E] focus:bg-white focus:ring-2 focus:ring-[#7A5B3E]/15 autofill-neutral"
                required
              />
              <button
                type="button"
                onClick={() => setShowPassword((visible) => !visible)}
                aria-label={showPassword ? 'Hide password' : 'Show password'}
                className="absolute right-3.5 top-1/2 -translate-y-1/2 text-stone-600 hover:text-stone-900 cursor-pointer"
              >
                {showPassword ? <HiOutlineEyeOff className="h-5 w-5" /> : <HiOutlineEye className="h-5 w-5" />}
              </button>
            </div>

            <div className="flex justify-end pt-0.5">
              <button
                type="button"
                onClick={() => {
                  handleClose();
                  navigate('/forgot-password');
                }}
                className="text-xs sm:text-[13px] font-medium text-stone-600 hover:text-stone-900 transition-colors cursor-pointer"
              >
                Forgot password?
              </button>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="!mt-4 flex h-11 sm:h-12 w-full items-center justify-center rounded-xl bg-[#715538] hover:bg-[#5f472e] text-white text-sm sm:text-[15px] font-semibold tracking-wide shadow-xs transition-all active:scale-[0.99] disabled:cursor-wait disabled:opacity-60 cursor-pointer"
            >
              {loading ? 'Signing In…' : 'Sign In'}
            </button>
          </form>

          <p className="mt-4 sm:mt-5 text-center text-xs sm:text-[13px] text-stone-500 font-normal">
            Don't have an account?{' '}
            <button
              type="button"
              onClick={() => {
                handleClose();
                navigate('/register');
              }}
              className="font-bold text-[#715538] hover:text-[#523d26] transition-colors cursor-pointer ml-0.5"
            >
              Create Account
            </button>
          </p>
        </section>

        {/* Right Column: Attractive Luxury Jewellery Image */}
        <section className="relative hidden md:block overflow-hidden bg-stone-900 select-none">
          <img
            src={authBannerUrl}
            alt="Neirah Fine Jewellery"
            className="absolute inset-0 h-full w-full object-cover object-center"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/75 via-black/20 to-black/10" />
          <div className="absolute inset-x-8 bottom-8 text-white">
            <p className="font-serif text-2xl sm:text-[28px] font-normal leading-snug tracking-tight drop-shadow-sm">
              More than<br />
              Jewellery<br />
              <span className="italic font-light">It’s a Feeling</span>
            </p>
            <div className="mt-3.5 h-0.5 w-12 bg-white/70" />
          </div>
        </section>
      </div>
    </Modal>
  );
}

import { useState, useRef, useEffect, useMemo, useCallback, useId } from 'react';
import { defaultCountries, parseCountry } from 'react-international-phone';
import { HiOutlineSearch, HiChevronDown, HiCheck, HiX } from 'react-icons/hi';

const POPULAR_ISO_CODES = ['in', 'us', 'gb', 'ae', 'ca', 'au', 'sg'];

export default function CountryCodeSelect({
  value = '+91',
  onChange,
  defaultCountry = 'in',
  disabled = false,
  size = 'md',
  direction = 'auto',
  className = '',
  buttonClassName = '',
  menuClassName = '',
  id,
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [dropUp, setDropUp] = useState(direction === 'up');
  const [maxListHeight, setMaxListHeight] = useState(250);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedIso, setSelectedIso] = useState(defaultCountry.toLowerCase());
  const [highlightedIndex, setHighlightedIndex] = useState(-1);

  const containerRef = useRef(null);
  const buttonRef = useRef(null);
  const menuRef = useRef(null);
  const searchInputRef = useRef(null);
  const listRef = useRef(null);
  const generatedId = useId();
  const selectId = id || generatedId;

  // Process all countries from react-international-phone
  const allCountries = useMemo(() => {
    return defaultCountries.map((c) => {
      const parsed = parseCountry(c);
      return {
        name: parsed.name,
        iso2: parsed.iso2.toLowerCase(),
        dialCode: `+${parsed.dialCode}`,
        rawDialCode: parsed.dialCode,
      };
    });
  }, []);

  // Sync selectedIso if value changes externally
  useEffect(() => {
    if (!value) return;
    const cleanValue = value.startsWith('+') ? value : `+${value}`;
    // If current selectedIso already matches this dialCode, keep it (e.g. CA vs US)
    const currentMatch = allCountries.find((c) => c.iso2 === selectedIso);
    if (currentMatch && currentMatch.dialCode === cleanValue) {
      return;
    }
    // Otherwise find the first country matching this dialCode
    const match = allCountries.find((c) => c.dialCode === cleanValue);
    if (match) {
      setSelectedIso(match.iso2);
    }
  }, [value, allCountries, selectedIso]);

  // Current active country
  const currentCountry = useMemo(() => {
    return (
      allCountries.find((c) => c.iso2 === selectedIso) ||
      allCountries.find((c) => c.iso2 === 'in') ||
      allCountries[0]
    );
  }, [allCountries, selectedIso]);

  // Popular list
  const popularCountries = useMemo(() => {
    return POPULAR_ISO_CODES.map((iso) =>
      allCountries.find((c) => c.iso2 === iso)
    ).filter(Boolean);
  }, [allCountries]);

  // Filtered countries based on search
  const filteredCountries = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return allCountries;

    const cleanDialQuery = q.replace(/^\+/, '');
    return allCountries.filter(
      (c) =>
        c.name.toLowerCase().includes(q) ||
        c.iso2.includes(q) ||
        c.rawDialCode.includes(cleanDialQuery)
    );
  }, [allCountries, searchQuery]);

  // Flat list for keyboard navigation
  const activeList = useMemo(() => {
    if (searchQuery.trim()) {
      return filteredCountries;
    }
    return [...popularCountries, ...allCountries];
  }, [searchQuery, filteredCountries, popularCountries, allCountries]);

  // Smart auto-flip & max height calculation
  const updateDropdownPosition = useCallback(() => {
    if (!containerRef.current) return;

    if (direction === 'down') {
      setDropUp(false);
      return;
    }
    if (direction === 'up') {
      setDropUp(true);
      return;
    }

    const rect = containerRef.current.getBoundingClientRect();
    const spaceBelowWindow = window.innerHeight - rect.bottom;
    const spaceAboveWindow = rect.top;
    const estimatedMenuHeight = 280;

    let containerSpaceBelow = spaceBelowWindow;
    let containerSpaceAbove = spaceAboveWindow;

    let parent = containerRef.current.parentElement;
    while (parent && parent !== document.body) {
      const style = window.getComputedStyle(parent);
      const overflowY = style.overflowY || '';
      const overflow = style.overflow || '';
      const isScrollable =
        overflowY === 'auto' ||
        overflowY === 'scroll' ||
        overflowY === 'hidden' ||
        overflow === 'auto' ||
        overflow === 'scroll' ||
        overflow === 'hidden';
      const isModal =
        parent.getAttribute('role') === 'dialog' ||
        parent.getAttribute('aria-modal') === 'true' ||
        parent.classList.contains('modal');

      if (isScrollable || isModal) {
        const parentRect = parent.getBoundingClientRect();
        const pBelow = parentRect.bottom - rect.bottom;
        const pAbove = rect.top - parentRect.top;
        if (pBelow < containerSpaceBelow) containerSpaceBelow = pBelow;
        if (pAbove < containerSpaceAbove) containerSpaceAbove = pAbove;
      }
      parent = parent.parentElement;
    }

    const effectiveSpaceBelow = Math.max(0, Math.min(spaceBelowWindow, containerSpaceBelow));
    const effectiveSpaceAbove = Math.max(0, Math.min(spaceAboveWindow, containerSpaceAbove));

    const shouldDropUp =
      effectiveSpaceBelow < estimatedMenuHeight && effectiveSpaceAbove > effectiveSpaceBelow;

    setDropUp(shouldDropUp);

    const availableSpace = shouldDropUp ? effectiveSpaceAbove : effectiveSpaceBelow;
    // Leave room for search bar (~52px) and margins (~16px)
    const calculatedListHeight = Math.max(140, Math.min(260, availableSpace - 68));
    setMaxListHeight(calculatedListHeight);
  }, [direction]);

  const handleToggle = () => {
    if (disabled) return;
    if (!isOpen) {
      updateDropdownPosition();
      setIsOpen(true);
    } else {
      setIsOpen(false);
    }
  };

  const handleSelect = (country) => {
    setSelectedIso(country.iso2);
    setIsOpen(false);
    setSearchQuery('');
    setHighlightedIndex(-1);
    if (onChange) {
      onChange(country.dialCode, country);
    }
    buttonRef.current?.focus();
  };

  // Keyboard navigation
  const handleKeyDown = (e) => {
    if (!isOpen) return;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHighlightedIndex((prev) => (prev < activeList.length - 1 ? prev + 1 : prev));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlightedIndex((prev) => (prev > 0 ? prev - 1 : 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      const target =
        highlightedIndex >= 0 && activeList[highlightedIndex]
          ? activeList[highlightedIndex]
          : activeList[0];
      if (target) {
        handleSelect(target);
      }
    } else if (e.key === 'Escape') {
      e.preventDefault();
      setIsOpen(false);
      buttonRef.current?.focus();
    }
  };

  const handleButtonKeyDown = (e) => {
    if (disabled) return;
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!isOpen) {
        updateDropdownPosition();
        setIsOpen(true);
      }
    }
  };

  // Handle outside click & escape key & window scroll/resize
  useEffect(() => {
    if (!isOpen) return;

    const handleClickOutside = (event) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target) &&
        (!menuRef.current || !menuRef.current.contains(event.target))
      ) {
        setIsOpen(false);
      }
    };

    const handleScroll = (event) => {
      // Do not close or re-orient if scroll happened inside the countries list
      if (menuRef.current && menuRef.current.contains(event.target)) {
        return;
      }
      updateDropdownPosition();
    };

    const handleResize = () => {
      updateDropdownPosition();
    };

    document.addEventListener('mousedown', handleClickOutside);
    window.addEventListener('scroll', handleScroll, true);
    window.addEventListener('resize', handleResize);

    // Auto-focus search input when opened
    const timer = setTimeout(() => {
      if (searchInputRef.current) {
        searchInputRef.current.focus();
      }
    }, 50);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      window.removeEventListener('scroll', handleScroll, true);
      window.removeEventListener('resize', handleResize);
      clearTimeout(timer);
    };
  }, [isOpen, updateDropdownPosition]);

  // Auto-scroll highlighted index into view
  useEffect(() => {
    if (isOpen && highlightedIndex >= 0 && listRef.current) {
      const optionEls = listRef.current.querySelectorAll('[role="option"]');
      if (optionEls[highlightedIndex]) {
        optionEls[highlightedIndex].scrollIntoView({ block: 'nearest' });
      }
    }
  }, [highlightedIndex, isOpen]);

  // Auto-scroll selected country into view on open
  useEffect(() => {
    if (!isOpen) {
      setHighlightedIndex(-1);
      setSearchQuery('');
      return;
    }

    const timer = setTimeout(() => {
      if (listRef.current) {
        const selectedEl = listRef.current.querySelector('[aria-selected="true"]');
        if (selectedEl) {
          selectedEl.scrollIntoView({ block: 'nearest' });
        }
      }
    }, 60);

    return () => clearTimeout(timer);
  }, [isOpen]);

  const getFlagEmoji = (iso2) => {
    if (!iso2 || iso2.length !== 2) return '';
    try {
      const codePoints = [...iso2.toUpperCase()].map((c) => 127397 + c.charCodeAt(0));
      return String.fromCodePoint(...codePoints);
    } catch {
      return iso2.toUpperCase();
    }
  };

  const renderFlag = (iso2, name, size = 'md') => {
    const isSmall = size === 'sm';
    return (
      <span className="relative flex shrink-0 items-center justify-center overflow-hidden rounded-[2px] shadow-2xs border border-stone-200/80 bg-stone-100">
        <img
          src={`https://flagcdn.com/w40/${iso2}.png`}
          srcSet={`https://flagcdn.com/w80/${iso2}.png 2x`}
          alt={`${name} flag`}
          className={`${isSmall ? 'h-3 w-4' : 'h-3.5 w-5'} object-cover block`}
          loading="lazy"
          onError={(e) => {
            e.currentTarget.style.display = 'none';
            if (e.currentTarget.nextSibling) {
              e.currentTarget.nextSibling.style.display = 'inline-block';
            }
          }}
        />
        <span
          style={{ display: 'none' }}
          className="text-[10px] leading-none select-none px-0.5"
          aria-hidden="true"
        >
          {getFlagEmoji(iso2)}
        </span>
      </span>
    );
  };

  const renderCountryItem = (country, index) => {
    const isSelected = country.iso2 === selectedIso;
    const isHighlighted = highlightedIndex === index;
    return (
      <button
        key={`${country.iso2}-${index}`}
        type="button"
        role="option"
        aria-selected={isSelected}
        onClick={() => handleSelect(country)}
        onMouseEnter={() => setHighlightedIndex(index)}
        className={`flex w-full items-center justify-between gap-2.5 px-3.5 py-2 text-left transition cursor-pointer ${
          isSelected
            ? 'bg-[#f7efe6] text-[#92704e] font-semibold'
            : isHighlighted
            ? 'bg-stone-100/90 text-stone-900 font-medium'
            : 'text-stone-700 hover:bg-stone-50'
        }`}
      >
        <div className="flex min-w-0 items-center gap-2.5">
          {renderFlag(country.iso2, country.name)}
          <span className="truncate">{country.name}</span>
        </div>
        <div className="flex shrink-0 items-center gap-2 font-mono text-xs text-stone-500">
          <span>{country.dialCode}</span>
          {isSelected && (
            <HiCheck className="h-4 w-4 text-[#92704e]" />
          )}
        </div>
      </button>
    );
  };

  return (
    <div ref={containerRef} className={`relative inline-block ${className}`}>
      {/* Trigger Button */}
      <button
        id={selectId}
        ref={buttonRef}
        type="button"
        disabled={disabled}
        onClick={handleToggle}
        onKeyDown={handleButtonKeyDown}
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        aria-label={`Country calling code, currently ${currentCountry.name} (${currentCountry.dialCode})`}
        className={
          buttonClassName ||
          'flex h-full items-center gap-1.5 px-2.5 text-stone-800 transition hover:bg-stone-50 border-r border-[#e9dfd3] outline-none cursor-pointer select-none'
        }
      >
        {renderFlag(currentCountry.iso2, currentCountry.name, size)}
        <span className={`${size === 'sm' ? 'text-xs' : 'text-xs sm:text-sm'} font-semibold tracking-wide text-stone-800`}>
          {currentCountry.dialCode}
        </span>
        <HiChevronDown
          className={`h-3 w-3 text-stone-400 transition-transform duration-200 ${
            isOpen ? 'rotate-180 text-[#92704e]' : ''
          }`}
        />
      </button>

      {/* Popover Dropdown */}
      {isOpen && (
        <div
          ref={menuRef}
          role="listbox"
          tabIndex={-1}
