import { useState, useRef, useEffect, useId, useCallback } from 'react';
import {
  HiOutlineCalendar,
  HiOutlineChevronLeft,
  HiOutlineChevronRight,
  HiOutlineChevronDown,
  HiOutlineClock,
  HiOutlineX,
} from 'react-icons/hi';

/**
 * Helper to format date into YYYY-MM-DD string
 */
export const formatDateToISO = (date) => {
  if (!date || isNaN(new Date(date).getTime())) return '';
  const d = new Date(date);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};

/**
 * Helper to format datetime into YYYY-MM-DDTHH:mm string
 */
export const formatDateTimeToISO = (date) => {
  if (!date || isNaN(new Date(date).getTime())) return '';
  const d = new Date(date);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
};

/**
 * Helper to format date for human-readable display
 */
export const formatDateDisplay = (dateStr, includeTime = false) => {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return String(dateStr);

  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const day = d.getDate();
  const month = months[d.getMonth()];
  const year = d.getFullYear();

  if (!includeTime) {
    return `${day} ${month} ${year}`;
  }

  let hours = d.getHours();
  const minutes = String(d.getMinutes()).padStart(2, '0');
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12 || 12;
  return `${day} ${month} ${year}, ${String(hours).padStart(2, '0')}:${minutes} ${ampm}`;
};

const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

const WEEKDAY_NAMES = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];

/**
 * Common Luxury DatePicker Component
 *
 * Matches the Neirah luxury design system.
 * Supports single date selection, optional time picker, quick month/year jumps,
 * smart auto-flip (opens upward when near bottom of modal/screen), custom triggers,
 * and standard YYYY-MM-DD or YYYY-MM-DDTHH:mm formats.
 */
export default function DatePicker({
  value,
  onChange,
  name,
  label,
  placeholder = 'Select date',
  required = false,
  disabled = false,
  includeTime = false,
  minDate,
  maxDate,
  direction = 'auto',
  openUpward = false,
  size = 'md',
  className = '',
  buttonClassName = '',
  popupClassName = '',
  children,
  id,
}) {
  const generatedId = useId();
  const inputId = id || generatedId;

  const [isOpen, setIsOpen] = useState(false);
  const [dropUp, setDropUp] = useState(openUpward || direction === 'up');
  const [isMonthYearPickerOpen, setIsMonthYearPickerOpen] = useState(false);

  // Parse initial selected date
  const parseDateValue = useCallback((val) => {
    if (!val) return null;
    const d = new Date(val);
    return isNaN(d.getTime()) ? null : d;
  }, []);

  const parsedVal = parseDateValue(value);

  // Month & year currently shown in calendar view
  const [viewDate, setViewDate] = useState(() => {
    if (parsedVal) {
      return new Date(parsedVal.getFullYear(), parsedVal.getMonth(), 1);
    }
    return new Date();
  });

  // Date currently selected
  const [selectedDate, setSelectedDate] = useState(parsedVal);

  // Time state (hours & minutes)
  const [timeHours, setTimeHours] = useState(() => {
    if (parsedVal) return parsedVal.getHours();
    return 12;
  });
  const [timeMinutes, setTimeMinutes] = useState(() => {
    if (parsedVal) return parsedVal.getMinutes();
    return 0;
  });

  const containerRef = useRef(null);
  const triggerRef = useRef(null);
  const popupRef = useRef(null);
  const isPointerDownRef = useRef(false);

  const handleTriggerPointerDown = () => {
    isPointerDownRef.current = true;
  };

  const handleClick = () => {
    if (disabled) return;
    isPointerDownRef.current = false;
    setIsOpen((prev) => !prev);
  };

  // Keyboard Tab focus automatically opens the date box
  const handleFocus = () => {
    if (disabled) return;
    // If focused by mouse click, handleClick handles toggle
    if (isPointerDownRef.current) return;
    setIsOpen(true);
  };

  // Tabbing away or blurring outside container closes the date box
  const handleBlur = (e) => {
    if (
      e.relatedTarget &&
      (containerRef.current?.contains(e.relatedTarget) || popupRef.current?.contains(e.relatedTarget))
    ) {
      return;
    }
    if (!e.relatedTarget) {
      return;
    }
    setIsOpen(false);
    setIsMonthYearPickerOpen(false);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Tab') {
      // When tabbing out to the next field, close this date box
      setIsOpen(false);
      setIsMonthYearPickerOpen(false);
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      setIsOpen((prev) => !prev);
    } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      setIsOpen(true);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      handleCancel();
    }
  };

  // Sync internal state when prop value changes
  useEffect(() => {
    const updated = parseDateValue(value);
    setSelectedDate(updated);
    if (updated) {
      setViewDate(new Date(updated.getFullYear(), updated.getMonth(), 1));
      setTimeHours(updated.getHours());
      setTimeMinutes(updated.getMinutes());
    }
  }, [value, parseDateValue]);

  // Handle smart auto-flip (open upward when near bottom of viewport or modal)
  useEffect(() => {
    if (openUpward || direction === 'up') {
      setDropUp(true);
      return;
    }
    if (direction === 'down') {
      setDropUp(false);
      return;
    }

    if (isOpen && triggerRef.current) {
      const rect = triggerRef.current.getBoundingClientRect();
      const estimatedPopupHeight = includeTime ? 420 : 360;
      let spaceBelow = window.innerHeight - rect.bottom;
      let spaceAbove = rect.top;

      let parent = containerRef.current?.parentElement;
      while (parent && parent !== document.body) {
        const style = window.getComputedStyle(parent);
        const overflow = style.overflowY || style.overflow;
        if (overflow === 'auto' || overflow === 'scroll' || overflow === 'hidden') {
          const parentRect = parent.getBoundingClientRect();
          const pBelow = parentRect.bottom - rect.bottom;
          const pAbove = rect.top - parentRect.top;
          if (pBelow < spaceBelow) spaceBelow = pBelow;
          if (pAbove < spaceAbove) spaceAbove = pAbove;
          break;
        }
        parent = parent.parentElement;
      }

      if (spaceBelow < estimatedPopupHeight && spaceAbove > spaceBelow) {
        setDropUp(true);
      } else {
        setDropUp(false);
      }
    }
  }, [isOpen, direction, openUpward, includeTime]);

  // Close on outside pointer click
  useEffect(() => {
    if (!isOpen) return;

    const handlePointerDown = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        handleCancel();
      }
    };

    const handleKeyDown = (e) => {
      if (e.key === 'Escape') {
        handleCancel();
      }
    };

    document.addEventListener('pointerdown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('pointerdown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen]);

  // Calendar math for days grid
  const currentYear = viewDate.getFullYear();
  const currentMonth = viewDate.getMonth();

  const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  const startingDayOfWeek = new Date(currentYear, currentMonth, 1).getDay(); // 0 = Sunday
  const daysInPrevMonth = new Date(currentYear, currentMonth, 0).getDate();

  // Trailing days from previous month
  const prevMonthDays = [];
  for (let i = startingDayOfWeek - 1; i >= 0; i--) {
    prevMonthDays.push({
      day: daysInPrevMonth - i,
      month: currentMonth - 1,
      year: currentYear,
      isCurrentMonth: false,
    });
  }

  // Days of current month
  const currentMonthDays = [];
  for (let d = 1; d <= daysInCurrentMonth; d++) {
    currentMonthDays.push({
      day: d,
      month: currentMonth,
      year: currentYear,
      isCurrentMonth: true,
    });
  }

  // Leading days of next month to fill complete 42-cell calendar grid
  const totalSlots = 42;
  const nextMonthDaysCount = totalSlots - (prevMonthDays.length + currentMonthDays.length);
  const nextMonthDays = [];
  for (let d = 1; d <= nextMonthDaysCount; d++) {
    nextMonthDays.push({
      day: d,
      month: currentMonth + 1,
      year: currentYear,
      isCurrentMonth: false,
    });
  }

  const allCalendarDays = [...prevMonthDays, ...currentMonthDays, ...nextMonthDays];

  // Month navigation handlers
  const handlePrevMonth = (e) => {
    e.stopPropagation();
    setViewDate(new Date(currentYear, currentMonth - 1, 1));
  };

  const handleNextMonth = (e) => {
    e.stopPropagation();
    setViewDate(new Date(currentYear, currentMonth + 1, 1));
  };

  // Day click handler - immediately applies selected date and closes popup
  const handleDayClick = (cell) => {
    const targetDate = new Date(cell.year, cell.month, cell.day);
    if (includeTime) {
      targetDate.setHours(timeHours, timeMinutes, 0, 0);
      setSelectedDate(targetDate);
      if (!cell.isCurrentMonth) {
        setViewDate(new Date(cell.year, cell.month, 1));
      }
      return;
    }

    setSelectedDate(targetDate);
    emitChange(formatDateToISO(targetDate));
    setIsOpen(false);
    setIsMonthYearPickerOpen(false);
  };

  // Quick select Today handler
  const handleSelectToday = (e) => {
    if (e) e.preventDefault();
    const today = new Date();
    setSelectedDate(today);
    if (includeTime) {
      today.setHours(timeHours, timeMinutes, 0, 0);
      emitChange(formatDateTimeToISO(today));
    } else {
      emitChange(formatDateToISO(today));
    }
    setIsOpen(false);
    setIsMonthYearPickerOpen(false);
  };

  // Emit change to consumer
  const emitChange = (valStr) => {
    if (!onChange) return;
    const syntheticEvent = {
      target: { name: name || '', value: valStr },
      currentTarget: { name: name || '', value: valStr },
    };
    onChange(valStr, syntheticEvent);
    if (name) {
      onChange(syntheticEvent);
    }
  };

  // Actions
  const handleApply = (e) => {
    if (e) e.preventDefault();
    if (!selectedDate) {
      emitChange('');
      setIsOpen(false);
      return;
    }

    const finalDate = new Date(selectedDate);
    if (includeTime) {
      finalDate.setHours(timeHours, timeMinutes, 0, 0);
      emitChange(formatDateTimeToISO(finalDate));
    } else {
      emitChange(formatDateToISO(finalDate));
    }
    setIsOpen(false);
    setIsMonthYearPickerOpen(false);
  };

  const handleClear = (e) => {
    if (e) e.preventDefault();
    setSelectedDate(null);
    emitChange('');
    setIsOpen(false);
    setIsMonthYearPickerOpen(false);
  };

  const handleCancel = (e) => {
    if (e) e.preventDefault();
    const original = parseDateValue(value);
    setSelectedDate(original);
    if (original) {
      setViewDate(new Date(original.getFullYear(), original.getMonth(), 1));
      setTimeHours(original.getHours());
      setTimeMinutes(original.getMinutes());
    }
    setIsOpen(false);
    setIsMonthYearPickerOpen(false);
  };

  // Quick Year jump in Month/Year view
  const handleYearChange = (delta) => {
    setViewDate(new Date(currentYear + delta, currentMonth, 1));
  };

  const handleSelectMonth = (mIdx) => {
    setViewDate(new Date(currentYear, mIdx, 1));
    setIsMonthYearPickerOpen(false);
  };

  // Check if a calendar cell matches the selected date
  const isCellSelected = (cell) => {
    if (!selectedDate) return false;
    return (
      selectedDate.getFullYear() === cell.year &&
      selectedDate.getMonth() === cell.month &&
      selectedDate.getDate() === cell.day
    );
  };

  // Check if a calendar cell is today
  const isCellToday = (cell) => {
    const today = new Date();
    return (
      today.getFullYear() === cell.year &&
      today.getMonth() === cell.month &&
      today.getDate() === cell.day
    );
  };

  // Check min / max date constraints
  const isCellDisabled = (cell) => {
    const d = new Date(cell.year, cell.month, cell.day);
    if (minDate) {
      const min = new Date(minDate);
      min.setHours(0, 0, 0, 0);
      if (d < min) return true;
    }
    if (maxDate) {
      const max = new Date(maxDate);
      max.setHours(23, 59, 59, 999);
      if (d > max) return true;
    }
    return false;
  };

  // Sizes for the input trigger
  const sizeStyles = {
    sm: 'h-9 px-2.5 text-xs rounded-lg gap-1.5',
    md: 'h-10 px-3.5 text-xs sm:text-[13px] rounded-xl gap-2',
    lg: 'h-11 px-4 text-sm rounded-xl gap-2.5',
  }[size] || 'h-9 px-2.5 text-xs rounded-lg gap-1.5';

  const displayString = formatDateDisplay(value, includeTime);

  return (
    <div
      ref={containerRef}
      className={`relative inline-block w-full font-sans text-left ${className}`}
    >
      {/* Optional Top Label */}
      {label && (
        <label
          htmlFor={inputId}
          className="block text-[11px] font-medium text-stone-700 mb-1 select-none"
        >
          {required && <span className="text-red-500 mr-1">*</span>}
          {label}
        </label>
      )}

      {/* Trigger: Either custom child OR default luxury input button */}
      {children ? (
        <div
          ref={triggerRef}
          tabIndex={disabled ? -1 : 0}
          role="button"
          onClick={handleClick}
          onPointerDown={handleTriggerPointerDown}
          onFocus={handleFocus}
          onBlur={handleBlur}
          onKeyDown={handleKeyDown}
          className="cursor-pointer outline-none"
        >
          {children}
        </div>
      ) : (
        <button
          ref={triggerRef}
          id={inputId}
          type="button"
          disabled={disabled}
          onClick={handleClick}
          onPointerDown={handleTriggerPointerDown}
          onFocus={handleFocus}
          onBlur={handleBlur}
          onKeyDown={handleKeyDown}
          className={`w-full flex items-center justify-between text-left font-medium transition-all duration-150 outline-none cursor-pointer bg-white border border-stone-200 hover:border-stone-300 shadow-2xs text-stone-800 ${
            sizeStyles
          } ${
            isOpen ? 'border-[#8c6b45] ring-2 ring-[#8c6b45]/15' : ''
          } ${
            disabled ? 'opacity-50 cursor-not-allowed bg-stone-100/60' : ''
          } ${buttonClassName}`}
        >
          <div className="flex items-center gap-2 truncate min-w-0">
            <HiOutlineCalendar
              className="w-3.5 h-3.5 shrink-0 text-[#8c6b45]"
            />
            <span
              className={`truncate ${
                !displayString ? 'text-stone-400 font-normal' : 'text-stone-800 font-medium'
              }`}
            >
              {displayString || placeholder}
            </span>
          </div>

          <div className="flex items-center gap-1 shrink-0 ml-1.5">
            {value && !disabled && (
              <span
                role="button"
                tabIndex={-1}
                onClick={(e) => {
                  e.stopPropagation();
                  handleClear(e);
                }}
                className="p-0.5 text-stone-400 hover:text-stone-700 hover:bg-stone-100 rounded-full transition-colors cursor-pointer"
                title="Clear date"
              >
                <HiOutlineX className="w-3 h-3" />
              </span>
            )}
            <HiOutlineChevronDown
              className={`w-3.5 h-3.5 text-stone-400 transition-transform duration-200 ${
                isOpen ? 'rotate-180 text-[#8c6b45]' : ''
              }`}
            />
          </div>
        </button>
      )}

      {/* ─── Luxury DatePicker Pop-up ─── */}
      {isOpen && (
        <div
          ref={popupRef}
          className={`absolute left-0 z-[100] w-[290px] sm:w-[310px] max-w-[calc(100vw-1.5rem)] p-3 sm:p-4 bg-white rounded-2xl border border-stone-200/90 shadow-2xl shadow-stone-900/15 backdrop-blur-md transition-all animate-scaleUp select-none ${
            dropUp
              ? 'bottom-full mb-1.5 origin-bottom'
              : 'top-full mt-1.5 origin-top'
          } ${popupClassName}`}
        >
          {/* Header: < Month Year ⌵ > */}
          <div className="flex items-center justify-between mb-2.5">
            <button
              type="button"
              onClick={handlePrevMonth}
              className="w-7 h-7 rounded-lg flex items-center justify-center text-stone-700 hover:bg-stone-100 hover:text-black transition-colors cursor-pointer"
              title="Previous Month"
            >
              <HiOutlineChevronLeft className="w-3.5 h-3.5 stroke-[2.5]" />
            </button>

            {/* Clickable Month & Year title */}
            <button
              type="button"
              onClick={() => setIsMonthYearPickerOpen(!isMonthYearPickerOpen)}
              className="flex items-center gap-1 px-2 py-0.5 rounded-lg text-xs sm:text-sm font-bold text-stone-900 hover:bg-stone-100 transition-colors cursor-pointer"
            >
              <span>{MONTH_NAMES[currentMonth]} {currentYear}</span>
              <HiOutlineChevronDown
                className={`w-3 h-3 text-stone-500 transition-transform duration-200 ${
                  isMonthYearPickerOpen ? 'rotate-180 text-[#8c6b45]' : ''
                }`}
              />
            </button>

            <button
              type="button"
              onClick={handleNextMonth}
              className="w-7 h-7 rounded-lg flex items-center justify-center text-stone-700 hover:bg-stone-100 hover:text-black transition-colors cursor-pointer"
              title="Next Month"
            >
              <HiOutlineChevronRight className="w-3.5 h-3.5 stroke-[2.5]" />
            </button>
          </div>

          {/* Quick Month & Year jump overlay */}
          {isMonthYearPickerOpen ? (
            <div className="py-1 space-y-2">
              {/* Year stepper */}
              <div className="flex items-center justify-between px-2 py-1 bg-stone-50 rounded-lg border border-stone-200/60">
                <button
                  type="button"
                  onClick={() => handleYearChange(-1)}
                  className="p-1 text-stone-600 hover:text-black hover:bg-white rounded transition-colors cursor-pointer"
                >
                  <HiOutlineChevronLeft className="w-3.5 h-3.5" />
                </button>
                <span className="font-bold text-xs text-stone-900">{currentYear}</span>
                <button
                  type="button"
                  onClick={() => handleYearChange(1)}
                  className="p-1 text-stone-600 hover:text-black hover:bg-white rounded transition-colors cursor-pointer"
                >
                  <HiOutlineChevronRight className="w-3.5 h-3.5" />
                </button>
              </div>

              {/* 12 Months Grid */}
              <div className="grid grid-cols-3 gap-1.5">
                {MONTH_NAMES.map((mName, idx) => {
                  const isCur = idx === currentMonth;
                  return (
                    <button
                      key={mName}
                      type="button"
                      onClick={() => handleSelectMonth(idx)}
                      className={`py-1.5 rounded-lg text-xs font-medium transition-colors cursor-pointer ${
                        isCur
                          ? 'bg-[#8c6b45] text-white shadow-xs font-semibold'
                          : 'bg-stone-50 text-stone-700 hover:bg-stone-100'
                      }`}
                    >
                      {mName.slice(0, 3)}
                    </button>
                  );
                })}
              </div>
            </div>
          ) : (
            <>
              {/* Weekday Row: Su Mo Tu We Th Fr Sa */}
              <div className="grid grid-cols-7 gap-1 text-center mb-1">
                {WEEKDAY_NAMES.map((day) => (
                  <span
                    key={day}
                    className="text-[10px] font-semibold text-stone-400 py-0.5"
                  >
                    {day}
                  </span>
                ))}
              </div>

              {/* 42-cell Days Grid */}
              <div className="grid grid-cols-7 gap-1 text-center">
                {allCalendarDays.map((cell, idx) => {
                  const selected = isCellSelected(cell);
                  const isToday = isCellToday(cell);
                  const disabledDay = isCellDisabled(cell);

                  return (
                    <button
                      key={idx}
                      type="button"
                      disabled={disabledDay}
                      onClick={() => !disabledDay && handleDayClick(cell)}
                      className={`h-7 w-7 sm:h-8 sm:w-8 mx-auto rounded-lg flex items-center justify-center text-xs transition-all duration-150 cursor-pointer ${
                        disabledDay
                          ? 'opacity-25 cursor-not-allowed hover:bg-transparent'
                          : selected
                          ? 'bg-[#8c6b45] text-white font-bold shadow-xs hover:opacity-90'
                          : !cell.isCurrentMonth
                          ? 'text-stone-300 hover:text-stone-600 hover:bg-stone-50'
                          : isToday
                          ? 'font-bold text-[#8c6b45] bg-[#8c6b45]/10'
                          : 'text-stone-800 hover:bg-stone-100 hover:text-stone-900 font-normal'
                      }`}
                    >
                      {cell.day}
                    </button>
                  );
                })}
              </div>
            </>
          )}

          {/* Optional Time Selector (for includeTime / datetime-local) */}
          {includeTime && (
            <div className="mt-3 pt-2.5 border-t border-stone-100 flex items-center justify-between text-xs">
              <div className="flex items-center gap-1 text-stone-600 font-medium">
                <HiOutlineClock className="w-3.5 h-3.5 text-[#8c6b45]" />
                <span>Time:</span>
              </div>
              <div className="flex items-center gap-1">
                <select
                  value={timeHours}
                  onChange={(e) => setTimeHours(Number(e.target.value))}
                  className="px-1.5 py-1 bg-stone-50 border border-stone-200 rounded text-xs font-semibold text-stone-800 focus:outline-none cursor-pointer"
                >
                  {Array.from({ length: 24 }).map((_, h) => {
                    const ampm = h >= 12 ? 'PM' : 'AM';
                    const h12 = h % 12 || 12;
                    return (
                      <option key={h} value={h}>
                        {String(h).padStart(2, '0')}:00 ({h12} {ampm})
                      </option>
                    );
                  })}
                </select>
                <span className="text-stone-400 font-bold">:</span>
                <select
                  value={timeMinutes}
                  onChange={(e) => setTimeMinutes(Number(e.target.value))}
                  className="px-1.5 py-1 bg-stone-50 border border-stone-200 rounded text-xs font-semibold text-stone-800 focus:outline-none cursor-pointer"
                >
                  {Array.from({ length: 60 }).map((_, m) => (
                    <option key={m} value={m}>
                      {String(m).padStart(2, '0')} min
                    </option>
                  ))}
                </select>
              </div>
            </div>
          )}

          {/* Footer */}
          <div className="mt-3 pt-2.5 border-t border-stone-100 flex items-center justify-between">
            <button
              type="button"
              onClick={handleClear}
              className="text-xs font-medium text-[#8c6b45] transition-colors cursor-pointer hover:underline"
            >
              Clear
            </button>

            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={handleSelectToday}
                className="px-2.5 py-1 rounded-lg border border-stone-200 bg-white hover:bg-stone-50 text-stone-700 text-xs font-medium transition-colors cursor-pointer shadow-2xs"
              >
                Today
              </button>

              {includeTime ? (
                <button
                  type="button"
                  onClick={handleApply}
                  className="px-3 py-1 rounded-lg bg-[#8c6b45] text-white text-xs font-semibold transition-colors shadow-xs cursor-pointer hover:opacity-90"
                >
                  Apply
                </button>
              ) : (
                <button
                  type="button"
                  onClick={handleCancel}
                  className="px-2.5 py-1 rounded-lg border border-stone-200 bg-white hover:bg-stone-50 text-stone-700 text-xs font-medium transition-colors cursor-pointer shadow-2xs"
                >
                  Close
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useRef, useEffect, useId, useMemo } from 'react';
import { HiOutlineChevronDown, HiCheck, HiOutlineSearch, HiOutlineX } from 'react-icons/hi';

/**
 * Common Luxury Dropdown Component for Frontend Storefront
 *
 * Matches the refined luxury jewelry ERP aesthetic:
 * - Rounded-xl trigger with subtle bronze-beige border (#e7ded3)
 * - Vertical subtle divider (|) before the dropdown chevron
 * - Rounded-2xl popover menu with warm ambient shadow
 * - Selected item highlighted in soft warm champagne tint (#f7efe5) with bronze checkmark (✓)
 * - Smooth scrollable options list with luxury scrollbar
 * - Smart auto-flip detecting both viewport and container boundaries (e.g. modals)
 * - Optional instant search filter for long lists (e.g. states, cities)
 *
 * @param {any} value - Currently selected value
 * @param {Function} onChange - Handler called on selection: (value) => void
 * @param {Array<string|number|object>} options - List of options. Can be primitives or { value, label, icon, disabled }
 * @param {string} [placeholder='Select an option'] - Placeholder text
 * @param {boolean} [disabled=false] - Disable interaction
 * @param {'auto'|'down'|'up'} [direction='auto'] - Direction to open the dropdown menu
 * @param {'sm'|'md'|'lg'} [size='md'] - Sizing preset (sm for compact bars, md for standard, lg for spacious)
 * @param {string} [className=''] - Container class name
 * @param {string} [buttonClassName=''] - Button trigger custom styling
 * @param {string} [menuClassName=''] - Menu popover custom styling
 * @param {React.ReactNode} [prefixIcon] - Icon to show at the start of the button
 * @param {boolean} [showChevron=true] - Show sleek dropdown chevron
 * @param {boolean} [showDivider=true] - Show vertical divider before chevron
 * @param {boolean} [searchable=false] - Whether to show a search filter at the top of the menu
 * @param {string} [searchPlaceholder='Search...'] - Search input placeholder
 * @param {string} [id] - Input id
 */
export default function Dropdown({
  value,
  onChange,
  options = [],
  placeholder = 'Select an option',
  disabled = false,
  direction = 'auto',
  size = 'md',
  className = '',
  buttonClassName = '',
  menuClassName = '',
  prefixIcon,
  showChevron = true,
  showDivider = true,
  searchable = false,
  searchPlaceholder = 'Search...',
  id,
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [dropUp, setDropUp] = useState(direction === 'up');
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const [searchQuery, setSearchQuery] = useState('');

  const containerRef = useRef(null);
  const buttonRef = useRef(null);
  const menuRef = useRef(null);
  const listRef = useRef(null);
  const searchInputRef = useRef(null);
  const isPointerDownRef = useRef(false);
  const generatedId = useId();
  const dropdownId = id || generatedId;

  // Normalize options into a consistent { value, label, ... } structure
  const normalizedOptions = useMemo(() => {
    return options.map((opt) => {
      if (typeof opt === 'object' && opt !== null) {
        return {
          value: opt.value !== undefined ? opt.value : opt.id,
          label: opt.label !== undefined ? opt.label : (opt.name || String(opt.value)),
          icon: opt.icon,
          disabled: Boolean(opt.disabled),
          raw: opt,
        };
      }
      return {
        value: opt,
        label: String(opt),
        disabled: false,
        raw: opt,
      };
    });
  }, [options]);

  // Filter options based on search query
  const filteredOptions = useMemo(() => {
    if (!searchQuery.trim()) return normalizedOptions;
    const q = searchQuery.toLowerCase().trim();
    return normalizedOptions.filter((opt) =>
      opt.label.toLowerCase().includes(q) || String(opt.value).toLowerCase().includes(q)
    );
  }, [normalizedOptions, searchQuery]);

  // Find currently selected option
  const selectedIndex = filteredOptions.findIndex(
    (opt) => String(opt.value) === String(value)
  );
  const selectedOption = normalizedOptions.find(
    (opt) => String(opt.value) === String(value)
  );

  // Sync highlightedIndex when dropdown opens or search changes
  useEffect(() => {
    if (isOpen) {
      setHighlightedIndex(selectedIndex >= 0 ? selectedIndex : 0);
    } else {
      setHighlightedIndex(-1);
      setSearchQuery('');
    }
  }, [isOpen]);

  useEffect(() => {
    if (isOpen && searchQuery) {
      setHighlightedIndex(0);
    }
  }, [searchQuery, isOpen]);

  // Autofocus search input when opened
  useEffect(() => {
    if (isOpen && searchable) {
      const timer = setTimeout(() => {
        searchInputRef.current?.focus();
      }, 50);
      return () => clearTimeout(timer);
    }
  }, [isOpen, searchable]);

  // Handle smart auto-flip (open upward if near screen bottom or container bottom)
  useEffect(() => {
    if (!isOpen || !buttonRef.current) return;
    if (direction === 'down') {
      setDropUp(false);
      return;
    }
    if (direction === 'up') {
      setDropUp(true);
      return;
    }

    const rect = buttonRef.current.getBoundingClientRect();
    const spaceBelowWindow = window.innerHeight - rect.bottom;
    const spaceAboveWindow = rect.top;
    const estimatedMenuHeight = 240;

    // Check if dropdown is inside a modal or dialog container
    const modalParent = buttonRef.current.closest('[role="dialog"], [aria-modal="true"], .modal');
    if (modalParent) {
      const parentRect = modalParent.getBoundingClientRect();
      const parentSpaceBelow = parentRect.bottom - rect.bottom;
      const parentSpaceAbove = rect.top - parentRect.top;

      if (parentSpaceBelow < estimatedMenuHeight && parentSpaceAbove > parentSpaceBelow) {
        setDropUp(true);
        return;
      }
    }

    if (spaceBelowWindow < estimatedMenuHeight && spaceAboveWindow > spaceBelowWindow) {
      setDropUp(true);
    } else {
      setDropUp(false);
    }
  }, [isOpen, direction]);

  // Auto-scroll selected/highlighted option into view
  useEffect(() => {
    if (isOpen && listRef.current) {
      const targetIndex = highlightedIndex >= 0 ? highlightedIndex : selectedIndex;
      if (targetIndex >= 0) {
        const optionEls = listRef.current.querySelectorAll('[role="option"]');
        if (optionEls[targetIndex]) {
          optionEls[targetIndex].scrollIntoView({ block: 'nearest' });
        }
      }
    }
  }, [isOpen, highlightedIndex, selectedIndex]);

  // Close on outside click or ancestor scroll
  useEffect(() => {
    const handleOutsideClick = (event) => {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    const handleScroll = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleOutsideClick);
      window.addEventListener('scroll', handleScroll, true);
    }
    return () => {
      document.removeEventListener('mousedown', handleOutsideClick);
      window.removeEventListener('scroll', handleScroll, true);
    };
  }, [isOpen]);

  const handleTriggerPointerDown = () => {
    isPointerDownRef.current = true;
  };

  const handleClick = () => {
    if (disabled) return;
    isPointerDownRef.current = false;
    setIsOpen((prev) => !prev);
  };

  // Focus handler: Opens dropdown when focused via keyboard Tab
  const handleFocus = () => {
    if (disabled) return;
    // If focus was triggered by a mouse click, do not auto-open here; handleClick handles toggle
    if (isPointerDownRef.current) return;

    // Focused via keyboard (Tab / Shift+Tab) -> automatically open dropdown list!
    setIsOpen(true);
    setHighlightedIndex(selectedIndex >= 0 ? selectedIndex : 0);
  };

  // Blur handler: When focus leaves the dropdown container, cleanly close it
  const handleBlur = (e) => {
    if (
      e.relatedTarget &&
      (containerRef.current?.contains(e.relatedTarget) || menuRef.current?.contains(e.relatedTarget))
    ) {
      return;
    }
    if (!e.relatedTarget) {
      return;
    }
    setIsOpen(false);
    setHighlightedIndex(-1);
  };

  // Keyboard navigation
  const handleKeyDown = (e) => {
    if (disabled) return;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (!isOpen) {
        setIsOpen(true);
      } else {
        setHighlightedIndex((prev) => {
          let next = prev + 1;
          while (next < filteredOptions.length && filteredOptions[next].disabled) {
            next += 1;
          }
          return next < filteredOptions.length ? next : prev;
        });
      }
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (!isOpen) {
        setIsOpen(true);
      } else {
        setHighlightedIndex((prev) => {
          let next = prev - 1;
          while (next >= 0 && filteredOptions[next].disabled) {
            next -= 1;
          }
          return next >= 0 ? next : prev;
        });
      }
    } else if (e.key === 'Enter') {
      if (!isOpen) {
        e.preventDefault();
        setIsOpen(true);
      } else if (highlightedIndex >= 0 && highlightedIndex < filteredOptions.length) {
        e.preventDefault();
        const opt = filteredOptions[highlightedIndex];
        if (!opt.disabled) {
          onChange?.(opt.value);
          setIsOpen(false);
        }
      }
    } else if (e.key === 'Escape' || e.key === 'Tab') {
      setIsOpen(false);
      setHighlightedIndex(-1);
    }
  };

  const handleSelect = (option, e) => {
    if (e) {
      e.stopPropagation();
      e.preventDefault();
    }
    if (option.disabled) return;
    onChange?.(option.value);
    setIsOpen(false);
  };

  // Sizing styles
  const sizeClasses = {
    sm: {
      button: 'h-9 px-2.5 sm:px-3 text-xs rounded-xl',
      menuItem: 'px-2.5 py-1.5 text-xs rounded-lg',
      divider: 'h-3.5',
      chevron: 'w-3.5 h-3.5',
      check: 'w-3 h-3',
    },
    md: {
      button: 'h-10 sm:h-11 px-3.5 sm:px-4 text-xs sm:text-[13px] rounded-xl sm:rounded-2xl',
      menuItem: 'px-3.5 py-2.5 text-xs sm:text-[13px] rounded-xl',
      divider: 'h-4',
      chevron: 'w-4 h-4',
      check: 'w-4 h-4',
    },
    lg: {
      button: 'h-12 px-5 text-sm sm:text-base rounded-2xl',
      menuItem: 'px-4 py-3 text-sm sm:text-base rounded-xl',
      divider: 'h-5',
      chevron: 'w-4 h-4',
      check: 'w-4 h-4',
    },
  }[size] || {
    button: 'h-10 px-3.5 text-xs rounded-xl',
    menuItem: 'px-3.5 py-2.5 text-xs rounded-xl',
    divider: 'h-4',
    chevron: 'w-4 h-4',
    check: 'w-4 h-4',
  };

  return (
    <div
      ref={containerRef}
      className={`relative inline-block w-full text-left ${className}`}
      onKeyDown={handleKeyDown}
    >
      {/* ─── Trigger Button ─── */}
      <button
        ref={buttonRef}
        type="button"
        id={dropdownId}
        disabled={disabled}
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        onClick={handleClick}
        onPointerDown={handleTriggerPointerDown}
        onFocus={handleFocus}
        onBlur={handleBlur}
        className={`w-full flex items-center justify-between gap-2.5 text-left transition-all duration-200 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed ${
          buttonClassName
            ? buttonClassName
            : `border border-[#e7ded3] bg-white text-stone-800 font-medium shadow-2xs hover:border-[#8b6f4e]/60 hover:bg-[#faf7f3]/40 focus:outline-none focus:ring-2 focus:ring-[#8b6f4e]/15 ${
                sizeClasses.button
              }`
        } ${isOpen ? 'border-[#8b6f4e] ring-2 ring-[#8b6f4e]/15' : ''}`}
      >
        <div className="flex items-center gap-2.5 min-w-0 flex-1">
          {prefixIcon && <span className="shrink-0 text-[#8b6f4e] flex items-center justify-center">{prefixIcon}</span>}
          {selectedOption ? (
            <span className="truncate text-stone-900 font-medium">
              {selectedOption.label}
            </span>
          ) : (
            <span className="truncate text-stone-400 font-normal">
              {placeholder}
            </span>
          )}
        </div>

        {/* Right Section: Optional vertical divider + Chevron */}
        <div className="flex items-center gap-2 shrink-0">
          {showChevron && showDivider && (
            <span className={`w-[1px] bg-[#e7ded3] ${sizeClasses.divider}`} />
          )}

          {showChevron && (
            <HiOutlineChevronDown
