                    {isSelected && (
                      <HiCheck
                        className={`${sizeClasses.check} text-[#8b6f4e] stroke-[2.5] shrink-0`}
                      />
                    )}
                  </div>
                );
              })
            )}
          </div>
        </div>
      )}
    </div>
  );
}

