        data-instgrm-captioned={captioned ? 'true' : undefined}
        style={{
          background: '#FFF',
          border: '0',
          borderRadius: '12px',
          margin: '0',
          maxWidth: '540px',
          minWidth: '326px',
          padding: '0',
          width: 'calc(100% - 2px)',
        }}
      >
        <div style={{ padding: '16px' }}>
          <a
            href={cleanUrl}
            target="_blank"
            rel="noopener noreferrer"
            style={{
              background: '#FFFFFF',
              lineHeight: '0',
              padding: '0',
              textAlign: 'center',
              textDecoration: 'none',
              width: '100%',
              display: 'block',
            }}
          >
            <div style={{ display: 'flex', flexDirection: 'row', alignItems: 'center' }}>
              <div
                style={{
                  backgroundColor: '#F4F4F4',
                  borderRadius: '50%',
                  flexGrow: 0,
