            ) : (
              formatProductPrice(salePrice) || "Price on request"
            )}
          </p>
          {!hasRange && hasDiscount && (
            <p className="text-[9px] sm:text-[10.5px] text-gray-400 line-through font-normal">
              {formatProductPrice(mrp)}
