  const [cart, setCart] = useState(() => {
    try {
      const saved = localStorage.getItem('jewels_cart');
      if (!saved) return [];
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? consolidateItems(parsed) : [];
    } catch {
      return [];
    }
  });

  const [loading, setLoading] = useState(false);
  const [cartDrawerOpen, setCartDrawerOpen] = useState(false);
  const openCartDrawer = useCallback(() => setCartDrawerOpen(true), []);
  const closeCartDrawer = useCallback(() => setCartDrawerOpen(false), []);

  const [cartTotals, setCartTotals] = useState({
    totalItems: 0,
    subtotal: 0,
    shipping: 0,
    tax: 0,
    total: 0,
  });

  const [countsData, setCountsData] = useState({
    cartCount: 0,
    wishlistCount: 0,
    orderCount: 0,
    returnOrderCount: 0,
  });

  // Calculate local fallback totals if needed
  const calculateTotals = useCallback((items) => {
    const totalItems = items.length;
    const subtotal = items.reduce(
      (sum, item) => sum + (Number(item.price) || 0) * (Number(item.quantity) || 1),
      0
    );
    const shipping = subtotal > 5000 || subtotal === 0 ? 0 : 250;
    const tax = Math.round(subtotal * 0.03); // 3% GST
    const total = subtotal + shipping + tax;
    return { totalItems, subtotal, shipping, tax, total };
  }, []);

  const updateCartFromResponse = useCallback((data) => {
    if (!data || !Array.isArray(data.items)) return;
    const consolidated = consolidateItems(data.items.map(formatCartItem));
    setCart((prev) => {
      const merged = consolidated.map((item) => {
        const localMatch = prev.find(
          (p) => (p.refId && p.refId === item.refId) || (p.id && p.id === item.id)
        );
        return {
          ...item,
          image: item.image || localMatch?.image || '',
          slug: item.slug || localMatch?.slug || '',
          title: item.title || localMatch?.title || item.name || '',
          name: item.name || localMatch?.name || item.title || '',
        };
      });
      localStorage.setItem('jewels_cart', JSON.stringify(merged));
      return merged;
    });
    setCartTotals({
      totalItems: data.totalItems ?? consolidated.length,
      subtotal: data.subtotal ?? calculateTotals(consolidated).subtotal,
      shipping: data.shipping ?? 0,
      tax: data.tax ?? 0,
      total: data.total ?? calculateTotals(consolidated).total,
    });
  }, [calculateTotals]);

  // Fetch cart from backend API
  const fetchCart = useCallback(async () => {
    if (isFetchingCartRef.current) return;
    isFetchingCartRef.current = true;
    try {
      setLoading(true);
      const res = await cartAPI.get();
      const data = res?.data?.data || res?.data || {};
      updateCartFromResponse(data);
    } catch (err) {
      console.warn('Failed to load cart from API, using local fallback:', err);
      setCart((currentCart) => {
        setCartTotals(calculateTotals(currentCart));
        return currentCart;
      });
    } finally {
      setLoading(false);
      isFetchingCartRef.current = false;
    }
  }, [calculateTotals, updateCartFromResponse]);

  // Fast counts fetcher (only asks for badge counts, never full cart)
  const fetchCounts = useCallback(async () => {
    if (isFetchingCountsRef.current) return null;
    isFetchingCountsRef.current = true;
    try {
      const res = await cartAPI.getCounts();
      const data = res?.data?.data || res?.data || {};
      const count = Number(data.cartCount ?? data.totalItems ?? 0);
      setCartTotals((prev) => ({
        ...prev,
        totalItems: count,
      }));
      setCountsData({
        cartCount: count,
        wishlistCount: Number(data.wishlistCount || 0),
        orderCount: Number(data.orderCount || 0),
        returnOrderCount: Number(data.returnOrderCount || 0),
      });
      return data;
    } catch (err) {
      console.warn('Failed to fetch badge counts:', err);
      return null;
    } finally {
      isFetchingCountsRef.current = false;
    }
  }, []);

  // Realtime Socket.IO synchronization for instant cart counts across tabs and devices
  useEffect(() => {
    joinUserSocketRooms({ userId: user?._id || user?.id });

    const unsubscribe = onCartCountUpdate((data) => {
      const count = Number(data?.cartCount ?? data?.totalItems ?? 0);
      setCartTotals((prev) => ({
        ...prev,
        totalItems: count,
      }));
    });

    return () => unsubscribe();
  }, [user]);

  // On mount or user/route change: fetch lightweight counts, only fetch full cart on cart/checkout pages
  useEffect(() => {
    fetchCounts();
    if (location.pathname === '/cart' || location.pathname === '/checkout') {
      fetchCart();
    }
  }, [user, location.pathname, fetchCounts, fetchCart]);

  // Add item to cart with instant 0ms optimistic UI and background API sync
  const addToCart = (product, quantity = 1, options = {}, explicitUser = null) => {
    if (!product) return;

    // Check authentication: user must be logged in to add to cart
    const accessToken = token || (typeof window !== 'undefined' ? localStorage.getItem('token') : null);
    const currentUser = explicitUser || user || (() => {
      try {
        const u = localStorage.getItem('user');
        return u ? JSON.parse(u) : null;
      } catch {
        return null;
      }
    })();

    if (!accessToken || !currentUser) {
      setCartDrawerOpen(false);
      if (typeof openLoginModal === 'function') {
        openLoginModal(async (authedUser) => {
          addToCart(product, quantity, options, authedUser);
        });
      } else {
        navigate('/login', { state: { from: location } });
      }
      return;
    }

    const itemType = resolveItemType(product, options);
    const isDiamond = itemType === 'diamond';
    const refId = extractRefId(product);
    if (!refId) {
      console.error('addToCart: Missing or invalid reference id', product);
      toast.error('Unable to add item: invalid product information');
      return;
    }
    const parsedQty = Math.max(1, parseInt(quantity, 10) || 1);
    const selectedMetal = resolveMetalName(options.selectedMetal || product.selectedMetal || '', product);
    const selectedSize = options.selectedSize || product.selectedSize || '';
    const title = product.basicInfo?.title || product.title || '';
    const price = Number(product.price || product.pricing?.salePrice || 0);
    const image = product.image || getPrimaryProductImage(product);
    const totalItemPrice = options.totalItemPrice || (price * parsedQty);
    const addedAt = options.addedAt || new Date().toISOString();
    const selectedAttributes = options.selectedAttributes || product.selectedAttributes || undefined;
    const slug = product.basicInfo?.slug || product.slug || '';

    // Increment request ID to track racing async requests
    const reqId = ++cartReqIdRef.current;

    // 1. INSTANT optimistic local update (Synchronous 0ms - no UI stutter)
    setCart((prev) => {
      const existingIndex = prev.findIndex(
        (item) => (item.refId || item.id) === refId
      );

      let updated;
      if (existingIndex > -1) {
        updated = [...prev];
        const nextQty = (Number(updated[existingIndex].quantity) || 0) + parsedQty;
        const currentUnitPrice = price || Number(updated[existingIndex].price) || 0;
        updated[existingIndex] = {
          ...updated[existingIndex],
          refId,
          id: refId,
          itemType,
          quantity: nextQty,
          price: currentUnitPrice,
          totalItemPrice: currentUnitPrice * nextQty,
          slug: slug || updated[existingIndex].slug,
          selectedMetal: selectedMetal || updated[existingIndex].selectedMetal,
          selectedSize: selectedSize || updated[existingIndex].selectedSize,
          selectedAttributes: selectedAttributes || updated[existingIndex].selectedAttributes,
        };
      } else {
        updated = [
          ...prev,
          {
            id: refId,
            refId,
            itemType,
            ...(isDiamond ? { productType: 'diamond' } : {}),
            slug,
            name: title,
            title,
            price,
            totalItemPrice,
            originalPrice: product.originalPrice || product.pricing?.mrp || null,
            image,
            category: product.category || '',
            quantity: parsedQty,
            selectedMetal,
            selectedSize,
            selectedAttributes,
            addedAt,
          },
        ];
      }
      const consolidated = consolidateItems(updated);
      localStorage.setItem('jewels_cart', JSON.stringify(consolidated));
      setCartTotals(calculateTotals(consolidated));
      return consolidated;
    });

    const isCartOrCheckoutPage = location.pathname === '/cart' || location.pathname === '/checkout';
    if (!options?.preventDrawer && !isCartOrCheckoutPage) {
      setCartDrawerOpen(true);
    }

    // Instant deduplicated feedback toast (never stacks multiple toasts)
    if (!options?.silent) {
      toast.success(`Added "${title}" to your bag!`, {
        id: 'cart-added',
        icon: '🛍️',
        duration: 2000,
        style: {
          background: '#22201e',
          color: '#f5f0eb',
          border: '1px solid rgba(198, 145, 60, 0.4)',
        },
      });
    }

    trackAddToCart(product, parsedQty, { shopperId: user?._id || user?.id });

    // 2. Silent non-blocking background API sync
    const payload = {
      refId,
      itemType,
      quantity: parsedQty,
      price,
      totalItemPrice,
      userId: currentUser?._id || currentUser?.id,
    };

    if (selectedMetal) payload.selectedMetal = selectedMetal;
    if (selectedSize) payload.selectedSize = selectedSize;
    if (selectedAttributes && typeof selectedAttributes === 'object') {
      const validEntries = Object.entries(selectedAttributes).filter(
        ([, val]) => val !== null && val !== undefined && val !== ''
      );
      if (validEntries.length > 0) {
        payload.selectedAttributes = Object.fromEntries(validEntries);
      }
    }

    cartAPI.add(payload)
      .then((res) => {
        if (reqId !== cartReqIdRef.current) return;
        const data = res?.data?.data || res?.data || {};
        updateCartFromResponse(data);
      })
      .catch((err) => {
        console.warn('Backend cart sync error:', err);
        if (err.response?.status === 401) {
          setCartDrawerOpen(false);
          if (typeof openLoginModal === 'function') {
            openLoginModal(async () => {
              addToCart(product, quantity, options);
            });
          }
        }
      });
  };

  // Update item quantity
  const updateQuantity = async (id, quantity) => {
    const targetId = extractRefId(id);
    if (!targetId) return;

    const parsedQty = parseInt(quantity, 10);
    if (parsedQty <= 0) {
      removeFromCart(targetId);
      return;
    }

    // Optimistic
    setCart((prev) => {
      const updated = prev.map((item) =>
        extractRefId(item) === targetId
          ? { ...item, quantity: parsedQty }
          : item
      );
      localStorage.setItem('jewels_cart', JSON.stringify(updated));
      setCartTotals(calculateTotals(updated));
      return updated;
    });

    // API call
    try {
      const res = await cartAPI.updateQuantity(targetId, parsedQty);
      const data = res?.data?.data || res?.data;
      updateCartFromResponse(data);
    } catch (err) {
      console.warn('Backend update quantity error:', err);
    }
  };

  // Remove item from cart
  const removeFromCart = async (id) => {
    const targetId = extractRefId(id);
    if (!targetId) return;

    const targetItem = cart.find(
      (item) => extractRefId(item) === targetId
    );
    if (targetItem) {
      trackRemoveFromCart(targetItem, targetItem.quantity || 1);
    }

    // Optimistic
    setCart((prev) => {
      const updated = prev.filter(
        (item) => extractRefId(item) !== targetId
      );
      localStorage.setItem('jewels_cart', JSON.stringify(updated));
      setCartTotals(calculateTotals(updated));
      return updated;
    });

    toast('Item removed from shopping bag', {
      icon: '🗑️',
      style: {
        background: '#22201e',
        color: '#f5f0eb',
      },
    });

    // API call
    try {
      await cartAPI.remove(targetId);
    } catch (err) {
      console.warn('Backend remove item error:', err);
    }
  };

  // Clear cart
  const clearCart = async () => {
    setCart([]);
    setCartTotals({
      totalItems: 0,
      subtotal: 0,
      shipping: 0,
      tax: 0,
      total: 0,
    });
    localStorage.removeItem('jewels_cart');

    try {
      await cartAPI.clear();
    } catch (err) {
      console.warn('Backend clear cart error:', err);
    }
  };

  const totalItems = cartTotals.totalItems || cart.length;
  const subtotal =
    cartTotals.subtotal ||
    cart.reduce((sum, item) => sum + (Number(item.price) || 0) * (Number(item.quantity) || 1), 0);
  const shipping = cartTotals.shipping || (subtotal > 5000 || subtotal === 0 ? 0 : 250);
  const tax = cartTotals.tax || Math.round(subtotal * 0.03);
  const total = cartTotals.total || subtotal + shipping + tax;

  return (
    <CartContext.Provider
      value={{
        cart,
        addToCart,
        updateQuantity,
        removeFromCart,
        clearCart,
        totalItems,
        orderCount: countsData.orderCount,
        returnOrderCount: countsData.returnOrderCount,
        countsData,
        subtotal,
        shipping,
        tax,
        total,
        loading,
        cartDrawerOpen,
        setCartDrawerOpen,
        openCartDrawer,
        closeCartDrawer,
        isCartOpen: cartDrawerOpen,
        setIsCartOpen: setCartDrawerOpen,
        fetchCounts,
        refreshCart: fetchCart,
      }}
    >
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  return context || defaultCartValue;
};

export default CartContext;

import { createContext, useContext, useEffect, useMemo, useState, useCallback, useRef } from 'react';
import { commonAPI } from '../api/services';

/* eslint-disable react/prop-types */

export const defaultStoreSettingsValue = {
  settings: {},
  footerSettings: {},
  topAnnouncement: {
    isEnabled: false,
    displayDirection: 'horizontal',
    autoplayInterval: 4000,
    items: [],
  },
  websiteConfig: null,
  navigation: [],
  revision: 0,
  theme: null,
  themeStyle: {},
  loading: false,
  refreshBootstrap: async () => null,
};

const StoreSettingsContext = createContext(defaultStoreSettingsValue);
const BOOTSTRAP_STORAGE_KEY = 'neirah_storefront_bootstrap_v3';

// Clear legacy cached bootstrap versions that may contain stale settings
if (typeof window !== 'undefined') {
  try {
    sessionStorage.removeItem('neirah_storefront_bootstrap_v1');
    sessionStorage.removeItem('neirah_storefront_bootstrap_v2');
  } catch {}
}

function getInitialCachedBootstrap() {
  if (typeof window === 'undefined') return null;
  try {
    const raw = sessionStorage.getItem(BOOTSTRAP_STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

export function StoreSettingsProvider({ children }) {
  const cached = useMemo(() => getInitialCachedBootstrap(), []);

  const [settings, setSettings] = useState(() => cached?.settings || {});
  const [footerSettings, setFooterSettings] = useState(() => cached?.footerSettings || {});
  const [topAnnouncement, setTopAnnouncement] = useState(() => cached?.topAnnouncement || {
    isEnabled: false,
    displayDirection: 'horizontal',
    autoplayInterval: 4000,
    items: [],
  });
  const [websiteConfig, setWebsiteConfig] = useState(() => cached?.websiteConfig || null);
  const [navigation, setNavigation] = useState(() => cached?.navigation || []);
  const [revision, setRevision] = useState(() => cached?.revision || 0);
  const [loading, setLoading] = useState(() => !cached);

  const currentRevisionRef = useRef(revision);
  useEffect(() => {
    currentRevisionRef.current = revision;
  }, [revision]);

  const applyBootstrapData = useCallback((data) => {
    if (!data) return;
    if (data.settings) {
      setSettings({
        ...data.settings,
        birthstones: {
          showOnStorefront: Boolean(
            data.settings?.birthstones?.showOnStorefront ?? data.birthstones?.showOnStorefront
          ),
        },
      });
    }
    if (data.footerSettings) setFooterSettings(data.footerSettings);
    if (data.topAnnouncement) setTopAnnouncement(data.topAnnouncement);
    if (data.websiteConfig) setWebsiteConfig(data.websiteConfig);
    if (Array.isArray(data.navigation)) setNavigation(data.navigation);
    if (typeof data.revision === 'number') {
      setRevision(data.revision);
      currentRevisionRef.current = data.revision;
    }

    try {
      sessionStorage.setItem(BOOTSTRAP_STORAGE_KEY, JSON.stringify(data));
    } catch {}
  }, []);

  const refreshBootstrap = useCallback(async (options = { fresh: true }) => {
    try {
      const res = await commonAPI.getBootstrap(options);
      const data = res?.data?.data;
      if (data) {
        applyBootstrapData(data);
      }
      return data;
    } catch (err) {
      console.warn('Failed to load storefront bootstrap data:', err);
      return null;
    }
  }, [applyBootstrapData]);

  // Initial load: always fetch fresh from backend
  useEffect(() => {
    let mounted = true;
    commonAPI.getBootstrap({ fresh: true })
      .then((res) => {
        if (!mounted) return;
        const data = res?.data?.data;
        if (data) applyBootstrapData(data);
      })
      .catch((err) => {
        console.warn('Initial bootstrap fetch error:', err);
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });

    return () => { mounted = false; };
  }, [applyBootstrapData]);

  // Smart Revalidation: Check revision on tab focus & gentle interval
  useEffect(() => {
    let isChecking = false;

    const checkFreshness = async () => {
      if (isChecking) return;
      isChecking = true;
      try {
        const res = await commonAPI.getRevision();
        const remoteRev = res?.data?.data?.revision;
        if (typeof remoteRev === 'number' && remoteRev !== currentRevisionRef.current) {
          // Admin updated something! Silently fetch fresh bootstrap data
          await refreshBootstrap({ fresh: true });
        }
      } catch {
        // Silently ignore revision ping failures
      } finally {
        isChecking = false;
      }
    };

    const handleFocus = () => {
      checkFreshness();
    };

    window.addEventListener('focus', handleFocus);
    const intervalTimer = window.setInterval(checkFreshness, 60_000); // Check every 60s

    return () => {
      window.removeEventListener('focus', handleFocus);
      window.clearInterval(intervalTimer);
    };
  }, [refreshBootstrap]);

  const theme = websiteConfig?.theme?.config || null;

  // Dynamically apply primary button colors across the entire storefront & portals
  useEffect(() => {
    const root = document.documentElement;
    const colors = settings?.themeColors || {};
    const btnBg = colors.buttonColor || settings?.buttonColor || theme?.colors?.primary || '#8b6f4e';
    const btnHover = colors.buttonHoverColor || settings?.buttonHoverColor || '#755c3e';
    const btnText = colors.buttonTextColor || '#ffffff';

    const topBarBg = colors.topBarBgColor || '#201e1b';
    const topBarText = colors.topBarTextColor || '#ffffff';
    const headerBg = colors.headerBgColor || '#201e1b';
    const headerText = colors.headerTextColor || '#ffffff';
    const couponBg = colors.couponBgColor || '#201e1b';
    const couponText = colors.couponTextColor || '#ffffff';
    const footerBg = colors.footerBgColor || '#0f0d0b';
    const footerText = colors.footerTextColor || '#c8b89e';

    root.style.setProperty('--btn-primary-bg', btnBg);
    root.style.setProperty('--btn-primary-hover', btnHover);
    root.style.setProperty('--btn-primary-text', btnText);

    root.style.setProperty('--storefront-topbar-bg', topBarBg);
    root.style.setProperty('--storefront-topbar-text', topBarText);
    root.style.setProperty('--storefront-header-bg', headerBg);
    root.style.setProperty('--storefront-header-text', headerText);
    root.style.setProperty('--storefront-coupon-bg', couponBg);
    root.style.setProperty('--storefront-coupon-text', couponText);
    root.style.setProperty('--storefront-footer-bg', footerBg);
    root.style.setProperty('--storefront-footer-text', footerText);
  }, [settings?.themeColors, theme?.colors?.primary]);

  useEffect(() => {
    const title = theme?.seo?.metaTitle;
    const description = theme?.seo?.metaDescription;
    if (!title && !description) return;
    if (title && (!document.title || document.title === 'Neirah Jewels | Fine Jewellery & Diamonds')) {
      document.title = title;
    }
    const meta = document.querySelector('meta[name="description"]');
    if (description && meta && (!meta.content || meta.content.includes('Discover handcrafted'))) {
      meta.content = description;
    }
  }, [theme?.seo?.metaTitle, theme?.seo?.metaDescription]);

  const themeStyle = useMemo(() => {
    const colors = theme?.colors || {};
    const savedButtonColors = settings?.themeColors || {};
    const btnBg = savedButtonColors.buttonColor || settings?.buttonColor || colors.primary || '#8b6f4e';
    const btnHover = savedButtonColors.buttonHoverColor || settings?.buttonHoverColor || '#755c3e';
    const btnText = savedButtonColors.buttonTextColor || settings?.buttonTextColor || '#ffffff';

    return {
      '--btn-primary-bg': btnBg,
      '--btn-primary-hover': btnHover,
      '--btn-primary-text': btnText,
      '--jewel-primary': btnBg,
      '--jewel-secondary': colors.secondary || '#EADCC8',
      '--jewel-paper': colors.background || '#FBF9F5',
      '--jewel-surface': colors.surface || '#FFFFFF',
      '--jewel-ink': colors.text || '#29251F',
      '--jewel-accent': colors.accent || btnBg,
      '--jewel-heading-font': `'${theme?.typography?.headingFont || 'Cormorant Garamond'}', Georgia, serif`,
      '--jewel-body-font': `'${theme?.typography?.bodyFont || 'Montserrat'}', system-ui, sans-serif`,
      '--jewel-radius': `${Math.min(32, Math.max(0, Number(theme?.borderRadius) || 0))}px`,
    };
  }, [theme, settings?.themeColors, settings?.buttonColor, settings?.buttonHoverColor, settings?.buttonTextColor]);

  return (
    <StoreSettingsContext.Provider
      value={{
        settings,
        footerSettings,
        topAnnouncement,
        websiteConfig,
        navigation,
        revision,
        theme,
        themeStyle,
        loading,
        refreshBootstrap,
      }}
    >
      {children}
    </StoreSettingsContext.Provider>
  );
}

// Provider and hook intentionally live together with this context.
// eslint-disable-next-line react-refresh/only-export-components
export function useStoreSettings() {
  const context = useContext(StoreSettingsContext);
  return context || defaultStoreSettingsValue;
}

import { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { wishlistAPI } from '../api/services';
import { useAuth } from './AuthContext';
import { joinUserSocketRooms, onWishlistCountUpdate } from '../services/socket';
import { trackAddToWishlist } from '../config/firebase';

/* eslint-disable react/prop-types, react-refresh/only-export-components */
const defaultWishlistValue = {
  wishlist: [],
  wishlistItems: [],
  wishlistMap: {},
  wishlistCount: 0,
  loading: false,
  isInitialLoaded: false,
  isWishlisted: () => false,
  toggleWishlist: async () => {},
  addToWishlist: async () => {},
  removeFromWishlist: async () => {},
  refreshWishlist: async () => {},
};

const WishlistContext = createContext(defaultWishlistValue);

export const WishlistProvider = ({ children }) => {
  const { user, token: authToken, openLoginModal } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();

  const inFlightPromiseRef = useRef(null);
  const lastFetchTimeRef = useRef(0);
  const wishlistItemsRef = useRef([]);

  const [wishlistItems, setWishlistItems] = useState(() => {
    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
    if (!token) {
      try {
        localStorage.removeItem('jewels_wishlist');
      } catch {}
      return [];
    }
    try {
      const saved = localStorage.getItem('jewels_wishlist');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  useEffect(() => {
    wishlistItemsRef.current = wishlistItems;
  }, [wishlistItems]);

  const [isInitialLoaded, setIsInitialLoaded] = useState(() => {
    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
    if (!token) return true;
    try {
      const saved = localStorage.getItem('jewels_wishlist');
      return Boolean(saved && JSON.parse(saved).length > 0);
    } catch {
      return false;
    }
  });

  const [wishlistMap, setWishlistMap] = useState(() => {
    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
    if (!token) return {};
    try {
      const saved = localStorage.getItem('jewels_wishlist');
      const list = saved ? JSON.parse(saved) : [];
      const map = {};
      list.forEach((item) => {
        const id = String(item.refId || item._id || item.id || '');
        if (id) map[id] = true;
      });
      return map;
    } catch {
      return {};
    }
  });
  const [loading, setLoading] = useState(false);

  // Fetch wishlist from backend with silent Stale-While-Revalidate caching
  const fetchWishlist = useCallback(async (options = {}) => {
    const { force = false, silent = false } = typeof options === 'boolean' ? { silent: options } : options;
    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
    if (!token && !user) {
      setIsInitialLoaded(true);
      return [];
    }

    const now = Date.now();
    // Throttle duplicate calls within 15s unless forced
    if (!force && lastFetchTimeRef.current && (now - lastFetchTimeRef.current < 15000)) {
      if (inFlightPromiseRef.current) return inFlightPromiseRef.current;
      return wishlistItemsRef.current;
    }

    if (inFlightPromiseRef.current) {
      return inFlightPromiseRef.current;
    }

    const fetchPromise = (async () => {
      // Never block or show full-screen skeletons if we already have items in memory
      if (!silent && wishlistItemsRef.current.length === 0) {
        setLoading(true);
      }
      try {
        const res = await wishlistAPI.get();
        const data = res?.data?.data || res?.data || {};
        const items = (Array.isArray(data.items) ? data.items : []).filter(
          (item) => item && typeof item === 'object'
        );

        setWishlistItems((prev) => {
          const prevKey = prev.map((i) => String(i.refId || i._id || i.id || '')).sort().join(',');
          const newKey = items.map((i) => String(i.refId || i._id || i.id || '')).sort().join(',');
          if (prevKey === newKey && prev.length === items.length && prev.length > 0) {
            return prev;
          }
          try {
            localStorage.setItem('jewels_wishlist', JSON.stringify(items));
          } catch {}
          return items;
        });

        const map = {};
        items.forEach((item) => {
          const id = String(item.refId || item._id || item.id || '');
          if (id) map[id] = true;
        });
        setWishlistMap(map);
        setWishlistCount(items.length);
        lastFetchTimeRef.current = Date.now();
        setIsInitialLoaded(true);
        return items;
      } catch (err) {
        console.warn('Failed to fetch wishlist from API:', err);
        return wishlistItemsRef.current;
      } finally {
        setLoading(false);
        inFlightPromiseRef.current = null;
      }
    })();

    inFlightPromiseRef.current = fetchPromise;
    return fetchPromise;
  }, [user]);

  const [wishlistCount, setWishlistCount] = useState(() => {
    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
    if (!token) return 0;
    try {
      const saved = localStorage.getItem('jewels_wishlist');
      return saved ? JSON.parse(saved).length : 0;
    } catch {
      return 0;
    }
  });

  // Fast counts fetcher (only asks for badge counts, never full wishlist)
  const fetchWishlistCount = useCallback(async () => {
    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
    if (!token && !user) {
      setWishlistCount(0);
      return;
    }
    try {
      const res = await wishlistAPI.getCounts();
      const data = res?.data?.data || res?.data || {};
      if (data.wishlistCount !== undefined) {
        setWishlistCount(Number(data.wishlistCount));
      }
    } catch (err) {
      console.warn('Failed to fetch wishlist count:', err);
    }
  }, [user]);

  // Realtime Socket.IO synchronization for instant counts across tabs and devices
  useEffect(() => {
    if (!user) return;
    joinUserSocketRooms({ userId: user?._id || user?.id });

    const unsubscribe = onWishlistCountUpdate((data) => {
      if (data?.wishlistCount !== undefined) {
        setWishlistCount(Number(data.wishlistCount));
      }
      if (data?.refId) {
        setWishlistMap((prev) => ({
          ...prev,
          [String(data.refId)]: Boolean(data.isWishlisted),
        }));
      }
    });

    return () => unsubscribe();
  }, [user?._id, user?.id]);

  const userId = user?._id || user?.id;

  // Sync count & prefetch wishlist in the background on mount or user change
  useEffect(() => {
    const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
    if (!token && !userId) {
      setWishlistItems([]);
      setWishlistMap({});
      setWishlistCount(0);
      setIsInitialLoaded(true);
      try {
        localStorage.removeItem('jewels_wishlist');
      } catch {}
      return;
    }
    fetchWishlistCount();
    // Silent prefetch so data is already loaded in memory before user clicks the heart icon!
    fetchWishlist({ silent: true });
  }, [userId, fetchWishlistCount, fetchWishlist]);

  // When navigating directly to /wishlist, perform silent background revalidation
  useEffect(() => {
    if (location.pathname === '/wishlist') {
      fetchWishlist({ silent: true });
    }
  }, [location.pathname, fetchWishlist]);

  // Check if a specific product is wishlisted
  const isWishlisted = useCallback(
    (productId) => {
      const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
      if (!token && !user) return false;
      if (!productId) return false;
      return !!wishlistMap[String(productId)];
    },
    [wishlistMap, user]
  );

  // Toggle item in wishlist with instant optimistic UI update & API sync
  const toggleWishlist = async (product, isCurrentlyWished = null, explicitUser = null) => {
    if (!product) return false;

    const accessToken = authToken || (typeof window !== 'undefined' ? localStorage.getItem('token') : null);
    const currentUser = explicitUser || user || (() => {
      try {
        const u = localStorage.getItem('user');
        return u ? JSON.parse(u) : null;
      } catch {
        return null;
      }
    })();

    if (!accessToken || !currentUser) {
      if (typeof openLoginModal === 'function') {
        openLoginModal(async (authedUser) => {
          await toggleWishlist(product, isCurrentlyWished, authedUser);
        });
      } else {
        navigate('/login', { state: { from: location } });
      }
      return false;
    }

    const refId = String(product.refId || product._id || product.id || '').trim();
    if (!refId) return false;

    const itemType =
      String(product.itemType || '').toLowerCase() === 'diamond' ||
      product.productType === 'diamond'
        ? 'diamond'
        : 'product';

    // Determine actual current status accurately
    const wasWishlisted =
      isCurrentlyWished !== null
        ? Boolean(isCurrentlyWished)
        : wishlistMap[refId] !== undefined
        ? Boolean(wishlistMap[refId])
        : Boolean(product.inWishlist);

    const willBeWishlisted = !wasWishlisted;

    // Instant optimistic UI update
    setWishlistMap((prev) => ({
      ...prev,
      [refId]: willBeWishlisted,
    }));

    setWishlistItems((prev) => {
      let next;
      if (willBeWishlisted) {
        const exists = prev.some((i) => String(i.refId || i._id || i.id) === refId);
        next = exists ? prev : [{ ...product, refId, itemType }, ...prev];
      } else {
        next = prev.filter((i) => String(i.refId || i._id || i.id) !== refId);
      }
      try {
        localStorage.setItem('jewels_wishlist', JSON.stringify(next));
      } catch {}
      return next;
    });

    // Instantly increment / decrement count!
    setWishlistCount((prev) => (willBeWishlisted ? prev + 1 : Math.max(0, prev - 1)));

    if (willBeWishlisted) {
      trackAddToWishlist(product, { shopperId: user?._id || user?.id });
      toast.success('Added to wishlist', {
        icon: '❤️',
        style: {
          background: '#22201e',
          color: '#f5f0eb',
          border: '1px solid rgba(225, 29, 72, 0.4)',
        },
      });
    } else {
      toast('Removed from wishlist', {
        icon: '🤍',
        style: {
          background: '#22201e',
          color: '#f5f0eb',
          border: '1px solid rgba(255, 255, 255, 0.1)',
        },
      });
    }

    if (accessToken || currentUser) {
      try {
        const res = await wishlistAPI.toggle({ refId, itemType });
        const result = res?.data?.data || {};

        if (result.isWishlisted !== undefined) {
          setWishlistMap((prev) => ({
            ...prev,
            [refId]: Boolean(result.isWishlisted),
          }));
        }

        if (result.items && Array.isArray(result.items)) {
          setWishlistItems(result.items);
          localStorage.setItem('jewels_wishlist', JSON.stringify(result.items));
          const nextMap = {};
          result.items.forEach((entry) => {
            const entryId = String(entry?.refId || entry?._id || entry?.id || '');
            if (entryId) nextMap[entryId] = true;
          });
          setWishlistMap(nextMap);
          setWishlistCount(result.items.length);
        } else if (result.wishlistCount !== undefined) {
          setWishlistCount(Number(result.wishlistCount));
        }
      } catch (err) {
        console.error('Error syncing wishlist with backend:', err);
      }
    }

    return willBeWishlisted;
  };

  // Remove item by refId
  const removeFromWishlist = async (refId) => {
    if (!refId) return;
    const strId = String(refId).trim();

    setWishlistMap((prev) => {
      const next = { ...prev };
      delete next[strId];
      return next;
    });
    setWishlistCount((prev) => Math.max(0, prev - 1));
    setWishlistItems((prev) => {
      const next = prev.filter((i) => String(i.refId || i._id || i.id) !== strId);
      try {
        localStorage.setItem('jewels_wishlist', JSON.stringify(next));
      } catch {}
      return next;
    });
    toast('Item removed from wishlist', {
      icon: '🤍',
      style: {
        background: '#22201e',
        color: '#f5f0eb',
      },
    });

    const token = localStorage.getItem('token');
    if (token || user) {
      try {
        await wishlistAPI.remove(strId);
      } catch (err) {
        console.error('Error removing from backend wishlist:', err);
      }
    }
  };

  // Clear entire wishlist
  const clearWishlist = async () => {
    setWishlistItems([]);
    setWishlistMap({});
    setWishlistCount(0);
    try {
      localStorage.removeItem('jewels_wishlist');
    } catch {}
    toast.success('Wishlist cleared');

    const token = localStorage.getItem('token');
    if (token || user) {
      try {
        await wishlistAPI.clear();
      } catch (err) {
        console.error('Error clearing backend wishlist:', err);
      }
    }
  };

  const addToWishlist = async (product) => {
    return toggleWishlist(product, false);
  };

  return (
    <WishlistContext.Provider
      value={{
        wishlistItems,
        wishlistMap,
        wishlistCount,
        fetchWishlistCount,
        loading,
        isInitialLoaded,
        isWishlisted,
        toggleWishlist,
        addToWishlist,
        removeFromWishlist,
        clearWishlist,
        refreshWishlist: fetchWishlist,
      }}
    >
      {children}
    </WishlistContext.Provider>
  );
};

