                  </div>
                </div>
              </div>
            </section>

            {/* Bottom Row / Submit */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 pt-6 border-t-[1.5px] border-dashed border-stone-400">
              <p className="flex items-center gap-1.5 text-xs text-stone-500">
