                        </div>

                        {/* Shared Specs Display */}
                        <ItemSpecsDisplay specs={specs} />

                        <div className="mt-2 inline-flex items-center rounded-lg border border-stone-200 bg-white shadow-2xs">
                        <button
                          type="button"
                          onClick={() => updateQuantity(item.id, (item.quantity || 1) - 1)}
