          </div>

            {/* Coupon Code */}
            <div className="border-t border-stone-100 pt-4">
              {appliedCoupon ? (
                <div className="rounded-xl border border-emerald-200/90 bg-gradient-to-br from-[#f2f9f4] via-[#f7fbf8] to-[#edf7f1] p-3.5 shadow-[0_2px_12px_rgba(16,185,129,0.06)] transition-all">
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex items-start gap-3">
                      <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-emerald-100 text-emerald-700 shadow-2xs">
                        <HiSparkles className="h-4.5 w-4.5 text-emerald-600 animate-pulse" />
                      </div>
                      <div className="space-y-1">
                        <div className="flex flex-wrap items-center gap-2">
                          <span className="inline-flex items-center gap-1.5 rounded-lg border border-dashed border-emerald-300 bg-white px-2.5 py-0.5 font-mono text-xs font-bold tracking-wider text-emerald-800 shadow-2xs">
                            <HiOutlineTag className="h-3.5 w-3.5 text-emerald-600" />
                            {appliedCoupon.coupon?.code || couponCode}
                          </span>
                          <span className="inline-flex items-center gap-1 rounded-full bg-emerald-100/90 px-2 py-0.5 text-[10px] font-semibold text-emerald-800">
                            <HiOutlineCheck className="h-3 w-3 stroke-[3]" /> Applied
                          </span>
                        </div>
                        <p className="text-xs font-medium text-emerald-900 leading-snug">
                          Yay! You save <span className="font-bold text-emerald-950 underline decoration-emerald-300 decoration-2 underline-offset-2">{formatPrice(discountAmount)}</span> on this order!
                        </p>
                      </div>
                    </div>
                    <button
                      type="button"
                      onClick={() => {
                        setAppliedCoupon(null);
                        setCouponCode('');
                        setCouponError('');
                        toast.success('Coupon removed');
                      }}
                      className="inline-flex items-center gap-1.5 rounded-full border border-stone-200 bg-white px-2.5 py-1 text-xs font-semibold text-stone-600 shadow-2xs transition hover:border-red-300 hover:bg-red-50 hover:text-red-600 cursor-pointer shrink-0"
                      title="Remove coupon"
                      aria-label="Remove coupon"
                    >
                      <span>Remove</span>
                      <span className="flex h-4 w-4 items-center justify-center rounded-full bg-stone-100 text-stone-500 transition-colors">
                        <HiX className="h-2.5 w-2.5" />
                      </span>
                    </button>
                  </div>
                </div>
              ) : (
                <div>
                  <label className="mb-2 flex items-center gap-1.5 text-xs font-bold text-stone-900">
                    <HiOutlineTag className="h-4 w-4 text-[#8c6536]" />
                    <span>Apply Coupon Code</span>
                  </label>
                  <div className="flex items-center gap-2">
                    <input
                      type="text"
                      className={`h-10 min-w-0 flex-1 rounded-xl border bg-white px-3 sm:px-3.5 text-base sm:text-xs text-stone-800 placeholder:text-stone-400 outline-none transition ${
                        couponError
                          ? 'border-red-400 focus:border-red-500 bg-red-50/20'
                          : 'border-stone-200 focus:border-[#8c6536] focus:ring-1 focus:ring-[#8c6536]'
                      }`}
                      value={couponCode}
                      onChange={(event) => {
                        setCouponCode(event.target.value);
                        if (couponError) setCouponError('');
                      }}
                      placeholder="Enter coupon code or gift card"
                      aria-label="Coupon code or gift card"
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          handleApplyCoupon(e);
                        }
                      }}
                    />
                    <button
                      type="button"
                      onClick={handleApplyCoupon}
                      disabled={couponLoading || !couponCode.trim()}
                      className="h-10 px-4 sm:px-5 rounded-xl bg-[#f2e6db] hover:bg-[#e8dacb] active:scale-[0.98] text-xs font-bold text-stone-900 transition disabled:opacity-75 disabled:cursor-not-allowed cursor-pointer flex items-center justify-center shrink-0 shadow-2xs"
                    >
                      {couponLoading ? 'Verifying...' : 'Apply'}
                    </button>
                  </div>
                  {couponError && (
                    <p className="mt-1.5 flex items-center gap-1.5 text-xs font-medium text-red-600">
                      <HiOutlineExclamationCircle className="h-4 w-4 shrink-0 text-red-500" />
                      <span>{couponError}</span>
                    </p>
                  )}
                </div>
              )}
            </div>

            {/* Price Breakdown */}
            <div className="space-y-2.5 border-t border-stone-100 pt-4 text-xs">
              <div className="flex justify-between text-stone-600">
                <span>Subtotal</span>
                <span className="font-semibold text-stone-900">{formatPrice(subtotal)}</span>
              </div>
              {appliedCoupon && (
                <div className="flex justify-between text-emerald-700 font-medium">
                  <span className="flex items-center gap-1.5 flex-wrap">
                    <HiOutlineTag className="h-3.5 w-3.5 text-emerald-600" />
                    <span>Coupon Savings ({appliedCoupon.coupon?.code || couponCode})</span>
                    {appliedCoupon.discount?.type === 'Percentage' && Number(appliedCoupon.discount?.value) > 0 ? (
                      <span className="text-[10.5px] font-semibold text-emerald-800 bg-emerald-100/70 px-1.5 py-0.5 rounded border border-emerald-200">
                        {appliedCoupon.discount.value}% OFF
                      </span>
                    ) : appliedCoupon.discount?.type === 'Fixed' && Number(appliedCoupon.discount?.value) > 0 ? (
                      <span className="text-[10.5px] font-semibold text-emerald-800 bg-emerald-100/70 px-1.5 py-0.5 rounded border border-emerald-200">
                        ₹{Number(appliedCoupon.discount.value).toLocaleString('en-IN')} OFF
                      </span>
                    ) : null}
                  </span>
                  <span className="font-bold text-emerald-700">−{formatPrice(discountAmount)}</span>
                </div>
              )}
              <div className="flex justify-between text-stone-600">
                <span className="flex items-center gap-1.5">
                  <span>Shipping</span>
                  <span
                    title="Free standard delivery"
                    className="inline-flex items-center text-stone-400 hover:text-stone-600 cursor-help transition-colors"
                  >
                    <HiOutlineInformationCircle className="w-4 h-4" />
                  </span>
                </span>
                <span className="font-semibold text-stone-900">
                  {shipping === 0 ? 'Free Shipping' : formatPrice(shipping)}
                </span>
              </div>
              <div className="flex justify-between text-stone-600">
                <span>Estimated GST (3%)</span>
                <span className="font-semibold text-stone-900">{formatPrice(tax)}</span>
              </div>
              {paymentMethod === 'cod' && codFee && (
                <div className="flex justify-between text-stone-600">
                  <span>COD advance due now</span>
                  <span className="font-semibold text-stone-900">{formatPrice(codDueNow)}</span>
                </div>
              )}
            </div>

            {/* Total */}
            <div className="flex items-center justify-between border-t border-stone-100 pt-4">
              <div>
                <h3 className="text-base font-bold text-stone-900">Total</h3>
                <p className="text-[11px] text-stone-400">Inclusive of all taxes</p>
                {isTestUser && (
                  <span className="inline-block mt-1 text-[10px] font-semibold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-full">
                    ⚡ Test Payment Mode (₹1)
                  </span>
                )}
              </div>
              <div className="text-right">
                <span className="text-xl sm:text-2xl font-bold font-sans text-stone-900">
                  {formatPrice(finalTotal)}
                </span>
                {isTestUser && calculatedTotal > 1 && (
                  <span className="block text-[11px] text-stone-400 line-through">
                    {formatPrice(calculatedTotal)}
                  </span>
                )}
              </div>
            </div>
          </aside>
        </form>

        {/* Mobile OTP Verification Modal */}
        <OtpVerificationModal
          isOpen={showOtpModal}
          onClose={() => setShowOtpModal(false)}
          phone={form.phone}
          countryCode={form.countryCode || '+91'}
          onVerified={handleOtpVerified}
          initialDevOtp={devOtp}
        />
      </div>
    </main>
  );
}

import { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import SEO from '../../components/common/SEO';
import axios from 'axios';
import toast from 'react-hot-toast';
import {
  HiOutlineCloudUpload,
  HiOutlineX,
  HiCheckCircle,
  HiOutlineUser,
  HiOutlineMail,
  HiOutlinePhotograph,
} from 'react-icons/hi';
import { IoDiamondOutline, IoChatbubbleEllipsesOutline, IoWalletOutline } from 'react-icons/io5';
import { FiLayers } from 'react-icons/fi';
import { TbCurrencyRupee } from 'react-icons/tb';
import api from '../../api/axios';
import { customInquiryAPI } from '../../api/services';
import PhoneInput from '../../components/common/PhoneInput';
import Dropdown from '../../components/common/Dropdown';

const DEFAULT_STONE_OPTIONS = [
  { value: 'Natural Diamond', label: 'Natural Diamond' },
  { value: 'Lab Grown Diamond', label: 'Lab Grown Diamond' },
];

const JEWELLERY_TYPES = [
  'Ring/Band',
  'Earrings',
  'Pendant',
  'Bracelets',
  'Necklace',
  'Other',
];

const METAL_OPTIONS = [
  { value: '9KT Gold', label: '9KT Gold' },
  { value: '14KT Gold', label: '14KT Gold' },
  { value: '18KT Gold', label: '18KT Gold' },
];

const BUDGET_OPTIONS = [
  { value: 'Under ₹25,000', label: 'Under ₹25,000' },
  { value: '₹25,000 - ₹50,000', label: '₹25,000 - ₹50,000' },
  { value: '₹50,000 - ₹1,00,000', label: '₹50,000 - ₹1,00,000' },
  { value: '₹1,00,000 - ₹2,50,000', label: '₹1,00,000 - ₹2,50,000' },
  { value: '₹2,50,000 - ₹5,00,000', label: '₹2,50,000 - ₹5,00,000' },
  { value: 'Above ₹5,00,000+', label: 'Above ₹5,00,000+' },
  { value: 'Flexible / Discuss Later', label: 'Flexible / Discuss Later' },
];

export default function CustomJewellery() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    stoneType: '',
    metalType: '',
    budget: '',
    comments: '',
  });

  const [countryCode, setCountryCode] = useState('+91');
  const [selectedJewelleryTypes, setSelectedJewelleryTypes] = useState([]);
  const [stoneOptions, setStoneOptions] = useState(DEFAULT_STONE_OPTIONS);
  const [images, setImages] = useState([]); // array of { file, preview, url, key, uploading, progress, error }
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [submittedInquiryId, setSubmittedInquiryId] = useState(null);
  const [isDragging, setIsDragging] = useState(false);

  const fileInputRef = useRef(null);

  useEffect(() => {
    document.title = 'Design Your Own Jewellery | Neirah Fine Jewellery';
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  // Fetch dynamic diamond types from lookup API
  useEffect(() => {
    let isMounted = true;
    const fetchDiamondTypes = async () => {
      try {
        const res = await api
          .get('/diamond-types/lookup')
          .catch(() => api.get('/diamond-types?limit=100'));
        const list = res.data?.data || [];
        if (Array.isArray(list) && list.length > 0 && isMounted) {
          const mapped = list
            .filter((item) => item && item.name && (!item.status || item.status === 'active'))
            .map((item) => ({
              value: item.name,
              label: item.name,
              id: item._id,
            }));
          if (mapped.length > 0) {
            setStoneOptions(mapped);
          }
        }
      } catch (err) {
        console.warn('Failed to load diamond types lookup:', err?.message);
      }
    };

    fetchDiamondTypes();
    return () => {
      isMounted = false;
    };
  }, []);

  const handleChange = (field) => (e) => {
    const val = e.target ? e.target.value : e;
    setFormData((prev) => ({ ...prev, [field]: val }));
  };

  const toggleJewelleryType = (type) => {
    setSelectedJewelleryTypes((prev) =>
      prev.includes(type) ? prev.filter((t) => t !== type) : [...prev, type]
    );
  };

  // ─── Direct Image Upload via Presigned URL ──────────────────────────────
  const uploadSingleImage = async (fileItem, index) => {
    const { file } = fileItem;
    const rawType = (file.type || '').split(';')[0].trim().toLowerCase();
    const contentType =
      rawType ||
      (/\.png$/i.test(file.name)
        ? 'image/png'
        : /\.webp$/i.test(file.name)
        ? 'image/webp'
        : 'image/jpeg');

    try {
      setImages((prev) =>
        prev.map((item, idx) => (idx === index ? { ...item, uploading: true, progress: 10 } : item))
      );

      // 1. Request presigned URL from backend
      const presignedRes = await api.post('/upload/presigned-url', {
        module: 'custom-inquiries',
        contentType,
      });

      const uploadData = presignedRes.data?.data;
      if (!uploadData?.uploadUrl || !uploadData?.key) {
        throw new Error('Could not get upload credentials');
      }

      const { uploadUrl, fileUrl, url, key } = uploadData;

      // 2. Direct PUT to Cloudflare R2
      await axios.put(uploadUrl, file, {
        headers: {
          'Content-Type': contentType,
        },
        onUploadProgress: (progressEvent) => {
          if (progressEvent.total) {
            const percent = Math.round((progressEvent.loaded * 100) / progressEvent.total);
            setImages((prev) =>
              prev.map((item, idx) =>
                idx === index ? { ...item, progress: Math.min(95, percent) } : item
              )
            );
          }
        },
      });

      const finalUrl = fileUrl || url;
      setImages((prev) =>
        prev.map((item, idx) =>
          idx === index
            ? { ...item, url: finalUrl, key, uploading: false, progress: 100 }
            : item
        )
      );
    } catch (err) {
      console.warn('Presigned upload failed; using local fallback:', err?.message);
      // Fallback: convert to base64 data URL so image is preserved
      try {
        const reader = new FileReader();
        reader.onloadend = () => {
          setImages((prev) =>
            prev.map((item, idx) =>
              idx === index
                ? { ...item, url: reader.result, key: `local-${Date.now()}`, uploading: false, progress: 100 }
                : item
            )
          );
        };
        reader.readAsDataURL(file);
      } catch {
        setImages((prev) =>
          prev.map((item, idx) =>
            idx === index
              ? { ...item, uploading: false, error: 'Upload failed' }
              : item
          )
        );
      }
    }
  };

  const handleFilesSelected = (fileList) => {
    if (!fileList || !fileList.length) return;
    const files = Array.from(fileList);

    const validFiles = files.filter((file) => {
      if (!file.type.startsWith('image/')) {
        toast.error(`"${file.name}" is not an image file`);
        return false;
      }
      if (file.size > 12 * 1024 * 1024) {
        toast.error(`"${file.name}" exceeds 12MB limit`);
        return false;
      }
      return true;
    });

    if (validFiles.length === 0) return;

    const newItems = validFiles.map((file) => ({
      file,
      preview: URL.createObjectURL(file),
      url: '',
      key: '',
      uploading: false,
      progress: 0,
      name: file.name,
      size: (file.size / (1024 * 1024)).toFixed(2),
    }));

    const startIndex = images.length;
    setImages((prev) => [...prev, ...newItems]);

    // Automatically trigger upload for each new file
    newItems.forEach((item, offset) => {
      uploadSingleImage(item, startIndex + offset);
    });
  };

  const removeImage = async (indexToRemove) => {
    const itemToRemove = images[indexToRemove];
    if (!itemToRemove) return;

    if (itemToRemove.preview && itemToRemove.preview.startsWith('blob:')) {
      URL.revokeObjectURL(itemToRemove.preview);
    }
    setImages((prev) => prev.filter((_, idx) => idx !== indexToRemove));

    // Delete from Cloudflare R2 if it was already uploaded
    const targetKey = itemToRemove.key;
    if (targetKey && !String(targetKey).startsWith('local-') && !String(targetKey).startsWith('blob:')) {
      try {
        await api.delete('/upload', {
          data: { key: targetKey },
        });
      } catch (err) {
        console.warn('Failed to delete reference image from Cloudflare R2:', err?.message);
      }
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFilesSelected(e.dataTransfer.files);
    }
  };

  // ─── Submit Custom Inquiry ──────────────────────────────────────────────
  const handleSubmit = async (e) => {
    e.preventDefault();

    // Client-side validation
    if (!formData.name.trim()) {
      toast.error('Please enter your name');
      return;
    }
    if (!formData.email.trim() || !/^\S+@\S+\.\S+$/.test(formData.email.trim())) {
      toast.error('Please enter a valid email address');
      return;
    }
    if (!formData.phone.trim()) {
      toast.error('Please enter your phone number');
      return;
    }
    if (!formData.stoneType) {
      toast.error('Please select a stone type');
      return;
    }
    if (selectedJewelleryTypes.length === 0) {
      toast.error('Please select at least one jewellery type');
      return;
    }
    if (!formData.metalType) {
      toast.error('Please select a metal type');
      return;
    }
    if (!formData.budget) {
      toast.error('Please select a budget range');
      return;
    }

    // Check if any image is currently uploading
    const stillUploading = images.some((img) => img.uploading);
    if (stillUploading) {
      toast('Images are still uploading, please wait a moment...', { icon: '⏳' });
      return;
    }

    try {
      setIsSubmitting(true);

      const referenceImagesPayload = images
        .filter((img) => img.url)
        .map((img) => ({
          url: img.url,
          key: img.key || '',
        }));

      const payload = {
        customer: {
          name: formData.name.trim(),
          email: formData.email.trim().toLowerCase(),
          phone: {
            countryCode: countryCode.replace(/^\+/, ''),
            number: formData.phone.trim(),
          },
        },
        requirements: {
          stoneType: formData.stoneType,
          jewelryTypes: selectedJewelleryTypes,
          metalType: formData.metalType,
          budget: formData.budget,
          comments: formData.comments.trim(),
        },
        referenceImages: referenceImagesPayload,
      };

      const res = await customInquiryAPI.create(payload);
      const createdId = res.data?.data?._id || res.data?.data?.id || 'NEI-CUSTOM';
      setSubmittedInquiryId(createdId);
      setIsSubmitted(true);
      toast.success('Your custom jewellery design inquiry has been submitted!', {
        icon: '💍',
        duration: 5000,
      });
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err) {
      console.error('Failed to submit custom inquiry:', err);
      toast.error(
        err.response?.data?.message || 'Failed to submit inquiry. Please try again or contact us.'
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleReset = () => {
