      .then((webRes) => {
        if (!mounted) return;
        const allBanners = Array.isArray(webRes?.data?.data) ? webRes.data.data : [];

        // 1. Hero banners
        const heroList = allBanners.filter((b) => b.display?.type === 'herobanner');
