          heroList.map((banner) => {
            const url = banner.image?.url || '';
            const isVid = banner.image?.mediaType === 'video' || /\.(mp4|webm|mov|m4v)(?:[?#]|$)/i.test(url);
            return {
              _id: banner._id,
              title: banner.content?.title || '',
              link: banner.link || banner.appStoreUrl || '',
