        );

    let diamondCost = isColorStone
      ? Number(v.sideDiamondCost || 0)
      : Number(
          v.diamondCost ||
          (Number(v.centerDiamondCost || 0) + Number(v.sideDiamondCost || 0)) ||
          v.sideDiamondCost ||
          v.centerDiamondCost ||
