            {/* ─── ADD TO CART Button Row ─── */}
            <div className="pt-2">
              <button
                type="button"
                onClick={handleAddToCart}
                disabled={addingToCart}
                className="w-full py-4 bg-[#141414] hover:bg-black active:scale-[0.99] text-white font-bold text-xs uppercase tracking-widest rounded-lg shadow-md transition-all cursor-pointer flex items-center justify-center gap-2"
              >
                {addingToCart ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    <span>ADDING TO BAG...</span>
                  </>
                ) : (
                  <span>ADD TO CART</span>
                )}
              </button>
            </div>

            {/* Delivery Estimate Bar (Matches Screenshot 3) */}
            <div className="text-center pt-1 text-xs text-stone-500">
              Order Now for estimated delivery by <strong className="text-stone-800 font-semibold">{deliveryDateString}</strong>
            </div>

            {/* ══════════════════════════════════════════════════════════
                THE NEIRAH DIFFERENCE (Matches Reference Screenshot)
            ═══════════════════════════════════════════════════════════ */}
            <div className="rounded-2xl border border-stone-200 bg-white p-5 sm:p-6 mb-6 shadow-2xs">
              <h3 className="text-xs font-bold uppercase tracking-wider text-stone-900 pb-3.5 border-b border-stone-200 font-sans">
                THE NEIRAH DIFFERENCE
              </h3>


              <ProductTrustBadges
                isGold={isGold}
                certificateUrl={certificateUrl}
                onOpenCertificate={openCertificateModal}
              />
            </div>


            {/* ══════════════════════════════════════════════════════════
                ACCORDIONS: PRODUCT DESCRIPTION, SPECIFICATION, PRICE BREAK UP & ORIGIN
            ═══════════════════════════════════════════════════════════ */}
            <ProductAccordions
              product={product}
              productSpecs={productSpecs}
              isGold={isGold}
              breakdown={breakdown}
            />
          </div>
        </div>

        {/* ─── CUSTOMER REVIEWS & RATINGS SECTION ─── */}
        <ProductReviewsSection
          reviewsLoading={reviewsLoading}
          sortedReviews={sortedReviews}
        />

        {/* ─── MOST LIKED PIECES ─── */}
        <ProductSimilarPieces mostLikedProducts={mostLikedProducts} />
      </div>

      {/* ─── Luxury High-Resolution Image Viewer Lightbox Modal ─── */}
      <ProductImageLightboxModal
        isOpen={lightboxIndex !== null}
        lightboxIndex={lightboxIndex}
        setLightboxIndex={setLightboxIndex}
        onClose={closeLightbox}
        galleryImages={galleryImages}
        selectedColor={selectedColor}
        setSelectedColor={setSelectedColor}
        modalColorsToRender={modalColorsToRender}
      />

      {/* ─── Category Size Chart Download Modal ─── */}
      <ProductSizeGuideModal
        isOpen={showSizeModal}
        onClose={() => setShowSizeModal(false)}
        sizeChart={sizeChart}
        categoryName={categoryName}
      />

      {/* ─── Luxury Authenticity & Grading Certificate Viewer Modal ─── */}
      <ProductCertificateModal
        isOpen={showCertificateModal}
        onClose={closeCertificateModal}
        certificateUrl={certificateUrl}
        product={product}
      />

      {/* ─── Mobile Sticky Bottom Action Bar ─── */}
      <ProductMobileBottomBar
        currentPrice={currentPrice}
        formatPrice={formatPrice}
        handleAddToCart={handleAddToCart}
        addingToCart={addingToCart}
        handleToggleWishlist={handleToggleWishlist}
        isItemWishlisted={isItemWishlisted}
      />

      {/* ─── Luxury Share Modal ─── */}
      <ProductShareModal
        isOpen={shareModalOpen}
        onClose={() => setShareModalOpen(false)}
        product={product}
        galleryImages={galleryImages}
        currentPrice={currentPrice}
        formatPrice={formatPrice}
      />

      {/* ─── Write a Review Modal ─── */}
      <ProductWriteReviewModal
        isOpen={showReviewModal}
        onClose={() => setShowReviewModal(false)}
        newReview={newReview}
        setNewReview={setNewReview}
        onSubmit={handleReviewSubmit}
        submittingReview={submittingReview}
      />

      {/* Similar Products Bottom Slide-Up Drawer */}
      <SimilarProductsDrawer
        open={similarDrawerOpen}
        onClose={() => setSimilarDrawerOpen(false)}
        productId={product?._id || product?.id}
        currentProduct={product}
      />
    </div>
  );
}

import api from '../../api/axios';
import { useStoreSettings } from '../../contexts/StoreSettingsContext';
import { useEffect, useState, useMemo, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import SEO from '../../components/common/SEO';
import { HiOutlineAdjustments, HiOutlineX, HiOutlineTrash, HiOutlineChevronLeft, HiOutlineChevronRight, HiOutlineTag, HiOutlineCheck, HiOutlineInformationCircle } from 'react-icons/hi';
import toast from 'react-hot-toast';
import ProductCard from '../../components/product/ProductCard';
import FilterSidebar from '../../components/product/FilterSidebar';
import Dropdown from '../../components/common/Dropdown';
import LuxuryDivider from '../../components/common/LuxuryDivider';
import { categoriesAPI, productsAPI, diamondsAPI, bannersAPI, couponsAPI } from '../../api/services';

const slugify = (value = '') => value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const aliases = { necklaces: 'pendant', bracelets: 'bangles-bracelets' };
const getItems = (response) => Array.isArray(response?.data?.data) ? response.data.data : response?.data?.data?.items || [];

export default function Shop({ defaultCategory = '' }) {
  const { settings, theme } = useStoreSettings();
  const themeColor = settings?.themeColors?.buttonColor || settings?.buttonColor || theme?.colors?.primary || '#8b6f4e';
  const themeTextColor = settings?.themeColors?.buttonTextColor || settings?.buttonTextColor || '#ffffff';
  const [params, setParams] = useSearchParams();

  const [categories, setCategories] = useState([]);
  const [dynamicFilters, setDynamicFilters] = useState([]);
  const [loadingFilters, setLoadingFilters] = useState(false);

  const [products, setProducts] = useState([]);
  const [pagination, setPagination] = useState({ totalDocs: 0, totalPages: 0 });
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isRefetching, setIsRefetching] = useState(false);
  const hasLoadedRef = useRef(false);
  const [error, setError] = useState('');
  const [navigationReady, setNavigationReady] = useState(false);
  const [mobileFilters, setMobileFilters] = useState(false);
  const [retry, setRetry] = useState(0);

  // URL Params
  const categoryParam = params.get('category') || defaultCategory || '';
  const category = categories.find((entry) => entry._id === categoryParam || slugify(entry.slug || entry.name) === (aliases[categoryParam] || categoryParam));
  const categoryId = category?._id || (/^[a-f0-9]{24}$/i.test(categoryParam) ? categoryParam : '');
  const isDiamondCategory = useMemo(() => {
    const rawCat = String(category?.slug || category?.name || categoryParam || '').toLowerCase().trim();
    return rawCat === 'diamond' || rawCat === 'diamonds' || category?.type === 'diamond';
  }, [category, categoryParam]);

  const featuredParam = params.get('featured') || '';
  const titleParam = params.get('title') || '';
  const [featuredData, setFeaturedData] = useState(null);
  const [displayBanner, setDisplayBanner] = useState(null);
  const [activeCoupons, setActiveCoupons] = useState([]);
  const [couponIndex, setCouponIndex] = useState(0);
  const [copiedCouponCode, setCopiedCouponCode] = useState(null);

  // Fetch all active promotional coupons (displayed one by one)
  useEffect(() => {
    let current = true;
    couponsAPI
      .getLookup()
      .then((res) => {
        if (!current) return;
        const list = Array.isArray(res?.data?.data)
          ? res.data.data
          : Array.isArray(res?.data)
          ? res.data
          : [];
        setActiveCoupons(list);
        setCouponIndex(0);
      })
      .catch(() => {
        if (current) setActiveCoupons([]);
      });
    return () => {
      current = false;
    };
  }, []);

  // Auto-rotate multiple coupons every 5 seconds
  useEffect(() => {
    if (activeCoupons.length <= 1) return;
    const timer = setInterval(() => {
      setCouponIndex((prev) => (prev + 1) % activeCoupons.length);
    }, 5000);
    return () => clearInterval(timer);
  }, [activeCoupons.length]);

  const handleCopyCoupon = (code) => {
    if (!code) return;
    if (navigator?.clipboard?.writeText) {
      navigator.clipboard.writeText(code);
    }
    setCopiedCouponCode(code);
    toast.success(`Coupon "${code}" copied to clipboard!`);
    setTimeout(() => {
      setCopiedCouponCode((prev) => (prev === code ? null : prev));
    }, 2500);
  };

  const currentCoupon = activeCoupons[couponIndex] || null;

  const getCouponDisplayText = (item) => {
    if (!item) return { code: '', discountPhrase: '' };
    const code = item.coupon?.code || item.code || '';
    const desc = item.coupon?.description || item.description || '';
    const discountType = item.discount?.type || 'Fixed';
    const discountVal = item.discount?.value || 0;
    const minOrder = item.discount?.minimumOrderAmount || 0;

    let discountPhrase = '';
    if (discountType === 'Fixed') {
      discountPhrase = `GET ${discountVal} RS OFF`;
    } else if (discountType === 'Percentage') {
      discountPhrase = `GET ${discountVal}% OFF`;
    } else if (desc) {
      discountPhrase = desc.toUpperCase();
    }

    let minOrderPhrase = '';
    if (minOrder && Number(minOrder) > 0) {
      minOrderPhrase = ` ON ORDERS ABOVE ₹${Number(minOrder).toLocaleString('en-IN')}`;
    }

    return {
      code,
      discountPhrase: `${discountPhrase}${minOrderPhrase}`,
    };
  };

  // Fetch Category Display Banner when category is selected
  useEffect(() => {
    const targetCat = categoryId || category?._id || categoryParam;
    if (!targetCat) {
      setDisplayBanner(null);
      return;
    }
    let current = true;
    bannersAPI
      .getCategoryDisplay({ category: targetCat, platform: 'web' })
      .then((res) => {
        if (!current) return;
        const bannerData = res?.data?.data?.banner || null;
        setDisplayBanner(bannerData);
      })
      .catch(() => {
        if (current) setDisplayBanner(null);
      });
    return () => { current = false; };
  }, [categoryId, category?._id, categoryParam]);

  // Fetch featured showcase details when featuredParam is present
  useEffect(() => {
    if (!featuredParam) {
      setFeaturedData(null);
      return;
    }
    let current = true;
    api
      .get(`/featured/${featuredParam}`)
      .then((res) => {
        if (!current) return;
        setFeaturedData(res.data?.data || null);
      })
      .catch(() => {});
    return () => { current = false; };
  }, [featuredParam]);

  const menuItem = params.get('menuItem') || '';
  const promoBanner = params.get('promoBanner') || '';
  const shopFor = params.get('shopFor') || '';
  const search = params.get('search') || '';
  const minPrice = params.get('minPrice') || '';
  const maxPrice = params.get('maxPrice') || '';
  const selectedDiamondType = params.get('diamondType') || '';
  const selectedDiamondShape = params.get('diamondShape') || params.get('shape') || '';
  const selectedDiamondColor = params.get('diamondColor') || params.get('color') || '';
  const selectedClarity = params.get('clarity') || params.get('diamondClarity') || '';
  const selectedCarat = params.get('carat') || '';
  const selectedCollection = params.get('collection') || '';
  const selectedMetal = params.get('metal') || '';
  const selectedStockStatus = params.get('stockStatus') || '';
  const selectedGemstone = params.get('gemstone') || params.get('stone_names') || '';
  const selectedGemstoneShape = params.get('gemstoneShape') || params.get('stone_shapes') || '';
  const selectedBirthMonth = params.get('birthMonth') || '';
  const sort = params.get('sort') || ((minPrice || maxPrice) ? 'price-low' : 'newest');
  const page = Math.max(1, Number(params.get('page')) || 1);
  const limit = [12, 24, 48].includes(Number(params.get('limit'))) ? Number(params.get('limit')) : 12;

  const scrollToTop = () => {
    try {
      window.scrollTo({ top: 0, left: 0, behavior: 'smooth' });
      document.documentElement.scrollTo({ top: 0, left: 0, behavior: 'smooth' });
      document.body.scrollTo({ top: 0, left: 0, behavior: 'smooth' });
    } catch {
      window.scrollTo(0, 0);
    }
  };

  const isFirstMount = useRef(true);
  useEffect(() => {
    if (isFirstMount.current) {
      isFirstMount.current = false;
      return;
    }
    scrollToTop();
    const timer = setTimeout(scrollToTop, 60);
    return () => clearTimeout(timer);
  }, [page, limit]);

  const goToPage = (newPage) => {
    if (newPage < 1 || (pagination.totalPages && newPage > pagination.totalPages)) return;
    const next = new URLSearchParams(params);
    if (newPage <= 1) {
      next.delete('page');
    } else {
      next.set('page', String(newPage));
    }
    setParams(next);
    scrollToTop();
    requestAnimationFrame(scrollToTop);
  };

  const getPageNumbers = (current, total) => {
    if (!total || total <= 1) return [1];
    if (total <= 7) {
      return Array.from({ length: total }, (_, i) => i + 1);
    }
    if (current <= 4) {
      return [1, 2, 3, 4, 5, '...', total];
    }
    if (current >= total - 3) {
      return [1, '...', total - 4, total - 3, total - 2, total - 1, total];
    }
    return [1, '...', current - 1, current, current + 1, '...', total];
  };

  // 1. Fetch Categories for navigation
  useEffect(() => {
    let current = true;
    categoriesAPI
      .getNavigation()
      .then((catsRes) => {
        if (!current) return;
        const items = getItems(catsRes);
        const sorted = [...(items || [])].sort((a, b) => {
          const diff = (Number(a.order) || 0) - (Number(b.order) || 0);
          if (diff !== 0) return diff;
          return String(a.name || a.title || '').localeCompare(String(b.name || b.title || ''));
        });
        setCategories(sorted);
      })
      .catch(() => {})
      .finally(() => {
        if (current) setNavigationReady(true);
      });

    return () => { current = false; };
  }, [retry]);

  // 2. Fetch Category-Specific Filters Dynamically (plus Diamond Attributes for Diamond category)
  useEffect(() => {
    let current = true;
    if (!dynamicFilters.length) {
      setLoadingFilters(true);
    }
    const featCatId = featuredData?.categoryId?._id || featuredData?.categoryId;
    const catQuery = categoryId || categoryParam || featCatId;

    const requests = [
      api.get('/filters', { params: catQuery ? { category: catQuery } : {} }),
      ...(isDiamondCategory ? [diamondsAPI.getAttributes().catch(() => null)] : []),
    ];

    Promise.all(requests)
      .then(([res, attrRes]) => {
        if (!current) return;
        const data = res.data?.data;
        let filterList = Array.isArray(data) ? data : (data?.filters || []);

        if (isDiamondCategory && attrRes?.data?.data) {
          const attrs = attrRes.data.data;
          const existingKeys = new Set(filterList.map((f) => f.key));
          const extraDiamondFilters = [];

          if (!existingKeys.has('price')) {
            extraDiamondFilters.push({ id: 'price', key: 'price', title: 'Price Range', type: 'range', enabled: true });
          }
          if (!existingKeys.has('diamondType') && Array.isArray(attrs.diamondTypes) && attrs.diamondTypes.length > 0) {
            extraDiamondFilters.push({
              id: 'diamondType',
              key: 'diamondType',
              title: 'Diamond Type',
              type: 'checkbox',
              enabled: true,
              options: attrs.diamondTypes.map((o) => ({ _id: o._id, name: o.name, value: o.name })),
            });
          }
          if (!existingKeys.has('diamondShape') && !existingKeys.has('shape') && Array.isArray(attrs.diamondShapes) && attrs.diamondShapes.length > 0) {
            extraDiamondFilters.push({
              id: 'diamondShape',
              key: 'diamondShape',
              title: 'Shape',
              type: 'checkbox',
              enabled: true,
              options: attrs.diamondShapes.map((o) => ({ _id: o._id, name: o.name, value: o.name })),
            });
          }
          if (!existingKeys.has('diamondColor') && !existingKeys.has('color') && Array.isArray(attrs.diamondColors) && attrs.diamondColors.length > 0) {
            extraDiamondFilters.push({
              id: 'diamondColor',
              key: 'diamondColor',
              title: 'Color',
              type: 'checkbox',
              enabled: true,
              options: attrs.diamondColors.map((o) => ({ _id: o._id, name: o.name, value: o.name })),
            });
          }
          if (!existingKeys.has('clarity') && !existingKeys.has('diamondClarity') && Array.isArray(attrs.diamondClarities) && attrs.diamondClarities.length > 0) {
            extraDiamondFilters.push({
              id: 'clarity',
              key: 'clarity',
              title: 'Clarity',
              type: 'checkbox',
              enabled: true,
              options: attrs.diamondClarities.map((o) => ({ _id: o._id, name: o.name, value: o.name })),
            });
          }

          if (extraDiamondFilters.length > 0) {
            filterList = [...filterList, ...extraDiamondFilters];
          }
        }

        setDynamicFilters(filterList);

        // When switching category, prune incompatible filter keys from URL params
        if (catQuery && filterList.length > 0) {
          const validKeys = new Set([
            'featured',
            'title',
            'category',
            'menuItem',
            'promoBanner',
            'search',
            'sort',
            'page',
            'limit',
            'minPrice',
            'maxPrice',
            'birthMonth',
            ...(isDiamondCategory ? ['diamondType', 'diamondShape', 'shape', 'diamondColor', 'color', 'diamondClarity', 'clarity', 'carat'] : []),
            ...filterList.map((f) => f.key),
          ]);
          const next = new URLSearchParams(params);
          let changed = false;
          for (const key of Array.from(next.keys())) {
            if (!validKeys.has(key)) {
              next.delete(key);
              changed = true;
            }
          }
          if (changed) {
            setParams(next, { replace: true });
          }
        }
      })
      .catch((err) => {
        console.error('Failed to load category filters:', err);
      })
      .finally(() => {
        if (current) setLoadingFilters(false);
      });

    return () => { current = false; };
  }, [categoryParam, categoryId, featuredData, isDiamondCategory]);

  // 3. Fetch Products (or Diamonds when Diamond category is selected)
  useEffect(() => {
    if (!navigationReady) return;
    let current = true;
    if (!hasLoadedRef.current) {
      setIsInitialLoading(true);
    } else {
      setIsRefetching(true);
    }
    setError('');

    if (isDiamondCategory) {
      const diamondQuery = {
        status: 'active',
        forweb: true,
        page,
        limit,
        sort: sort === 'price-low' ? 'price-asc' : sort === 'price-high' ? 'price-desc' : sort,
      };
      if (search) diamondQuery.search = search;
      if (minPrice) diamondQuery.minPrice = minPrice;
      if (maxPrice) diamondQuery.maxPrice = maxPrice;
      if (selectedDiamondType) diamondQuery.diamondType = selectedDiamondType;
      if (selectedDiamondShape) diamondQuery.diamondShape = selectedDiamondShape;
      if (selectedDiamondColor) diamondQuery.diamondColor = selectedDiamondColor;
      if (selectedClarity) diamondQuery.diamondClarity = selectedClarity;
      if (selectedCarat) diamondQuery.carat = selectedCarat;

      diamondsAPI
        .getAll(diamondQuery)
        .then((response) => {
          if (current) {
            hasLoadedRef.current = true;
            const rawDiamonds = getItems(response);
            const mappedDiamonds = rawDiamonds.map((d) => ({
              _id: d._id,
              id: d._id,
              itemType: 'diamond',
              productType: 'diamond',
              sku: d.sku || '',
              title: d.title || '',
              description: d.description || '',
              basicInfo: {
                title: d.title || '',
                slug: d.sku || String(d._id),
              },
              pricing: {
                salePrice: Number(d.price) || 0,
                mrp: Number(d.price) || 0,
              },
              image: d.image?.url || '',
              images: d.image?.url ? [d.image.url] : [],
              carat: d.carat,
              rate: d.rate,
              colorId: d.colorId,
              clarityId: d.clarityId,
              shapeId: d.shapeId,
              typeId: d.typeId,
            }));
            setProducts(mappedDiamonds);
            setPagination(response.data?.pagination || { totalDocs: mappedDiamonds.length, totalPages: 1 });
          }
        })
        .catch(() => {
          if (current) {
            setError('We could not load diamonds. Please try again.');
            setProducts([]);
          }
        })
        .finally(() => {
          if (current) {
            setIsInitialLoading(false);
            setIsRefetching(false);
          }
        });

      return () => { current = false; };
    }

    const query = {
      status: 'approved',
      forweb: true,
      page,
      limit,
      sort,
      includeFacets: true,
      includeGroups: true,
    };
    if (featuredParam) query.featured = featuredParam;
    if (categoryId || categoryParam) query.category = categoryId || categoryParam;
    if (promoBanner) query.promoBanner = promoBanner;
    if (menuItem) query.menuItem = menuItem;
    if (shopFor) query.shopFor = shopFor;
    if (search) query.search = search;
    if (minPrice) query.minPrice = minPrice;
    if (maxPrice) query.maxPrice = maxPrice;
    if (selectedDiamondType) query.diamondType = selectedDiamondType;
    if (selectedClarity) query.clarity = selectedClarity;
    if (selectedCarat) query.carat = selectedCarat;
    if (selectedCollection) query.collection = selectedCollection;
    if (selectedMetal) query.metal = selectedMetal;
    if (selectedStockStatus) query.stockStatus = selectedStockStatus;
    if (selectedGemstone) query.gemstone = selectedGemstone;
    if (selectedGemstoneShape) query.gemstoneShape = selectedGemstoneShape;
    if (selectedBirthMonth) {
      query.birthMonth = selectedBirthMonth.split(',').map((s) => s.trim()).filter(Boolean);
    }

    productsAPI
      .getAll(query)
      .then((response) => {
        if (current) {
          hasLoadedRef.current = true;
          setProducts(getItems(response));
          setPagination(response.data?.pagination || { totalDocs: getItems(response).length, totalPages: 1 });
        }
      })
      .catch(() => {
        if (current) {
          setError('We could not load the jewellery collection. Please try again.');
          setProducts([]);
        }
      })
      .finally(() => {
        if (current) {
          setIsInitialLoading(false);
          setIsRefetching(false);
        }
      });

    return () => { current = false; };
  }, [
    navigationReady,
    isDiamondCategory,
    featuredParam,
    categoryId,
    categoryParam,
    promoBanner,
    menuItem,
    search,
    minPrice,
    maxPrice,
    sort,
    page,
    limit,
    retry,
    shopFor,
    selectedDiamondType,
    selectedDiamondShape,
    selectedDiamondColor,
    selectedClarity,
    selectedCarat,
    selectedCollection,
    selectedMetal,
    selectedStockStatus,
    selectedGemstone,
    selectedGemstoneShape,
    selectedBirthMonth,
  ]);

  function updateFilters(changes) {
    const next = new URLSearchParams(params);
    next.delete('page');
    Object.entries(changes).forEach(([key, value]) => (value ? next.set(key, value) : next.delete(key)));
    setParams(next);
  }

  // Active filters check
  const filtersActive =
    !!featuredParam ||
    !!categoryParam ||
    !!promoBanner ||
    !!menuItem ||
    !!search ||
    !!minPrice ||
    !!maxPrice ||
    !!shopFor ||
    !!selectedDiamondType ||
    !!selectedDiamondShape ||
    !!selectedDiamondColor ||
    !!selectedClarity ||
    !!selectedCarat ||
    !!selectedCollection ||
    !!selectedMetal ||
    !!selectedStockStatus ||
    !!selectedGemstone ||
    !!selectedGemstoneShape ||
    !!selectedBirthMonth;

  const featuredTitle = featuredData?.name || titleParam || '';

  // Active chips array
  const activeChips = [];
  if (featuredParam) {
    activeChips.push({
      label: featuredTitle || 'Showcase',
      onRemove: () => updateFilters({ featured: '', title: '' }),
    });
  }
  if (category?.name) {
    activeChips.push({
      label: category.name,
      onRemove: () => updateFilters({ category: '', menuItem: '', promoBanner: '', title: '' }),
    });
  }
  if (promoBanner) {
    const bannerObj = (category?.promoBanners || []).find((b) => String(b._id) === String(promoBanner));
    activeChips.push({
      label: bannerObj?.title ? `Promo: ${bannerObj.title}` : 'Promo Banner',
      onRemove: () => updateFilters({ promoBanner: '' }),
    });
  }
  if (search) {
    activeChips.push({
      label: `Search: ${search}`,
      onRemove: () => updateFilters({ search: '' }),
    });
  }
  if (minPrice || maxPrice) {
    activeChips.push({
      label: `₹${minPrice || '0'} – ${maxPrice ? `₹${maxPrice}` : 'Any'}`,
      onRemove: () => {
        const nextFilter = { minPrice: '', maxPrice: '' };
        if (params.get('sort') === 'price-low') {
          nextFilter.sort = 'newest';
        }
        updateFilters(nextFilter);
      },
    });
  }

  const multiFilterKeys = [
    'birthMonth',
    'shopFor',
    'diamondType',
    'diamondShape',
    'shape',
    'diamondColor',
    'color',
    'diamondClarity',
    'clarity',
    'carat',
    'collection',
    'metal',
    'stockStatus',
    'gemstone',
    'gemstoneShape',
  ];

  multiFilterKeys.forEach((key) => {
    const raw = params.get(key) || '';
    if (!raw) return;
    const parts = raw.split(',').map((s) => s.trim()).filter(Boolean);
    parts.forEach((val) => {
      activeChips.push({
        label: key === 'birthMonth' ? `Birthstone: ${val}` : val,
        onRemove: () => {
          const nextParts = parts.filter((p) => p !== val);
          updateFilters({ [key]: nextParts.join(',') });
        },
      });
    });
  });

  const displayedProducts = products;
  const displayCount = pagination.totalDocs || products.length;

  // 1st display gold products, then silver products (unless explicit price sort or diamond catalog)
  const sortedDisplayedProducts = useMemo(() => {
    if (isDiamondCategory) return displayedProducts;
    const isPriceSorted = sort === 'price-low' || sort === 'price-high';
    if (isPriceSorted) return displayedProducts;
    return [...displayedProducts].sort((a, b) => {
      const isGoldA = (a.productType || '').toLowerCase() === 'gold' ? 0 : 1;
      const isGoldB = (b.productType || '').toLowerCase() === 'gold' ? 0 : 1;
      return isGoldA - isGoldB;
    });
  }, [displayedProducts, sort, isDiamondCategory]);

  // Page title: When nothing in filter, display 'All Jewellery'
  const pageTitle =
    featuredTitle ||
    titleParam ||
    category?.name ||
    (selectedBirthMonth ? `Birthstone: ${selectedBirthMonth}` : '') ||
    (search ? `Search: "${search}"` : (selectedCollection || 'All Jewellery'));

  const seoTitle = pageTitle ? `${pageTitle} | Fine Jewellery Collection` : 'Shop Fine Jewellery & Certified Diamonds';
  const seoDescription = category?.name
    ? `Explore our exclusive collection of handcrafted ${category.name}. Certified lab-grown diamonds, pure gold, and sterling silver pieces from Neirah Jewels.`
    : isDiamondCategory
      ? 'Browse certified lab-grown diamonds in all shapes and sizes. Sustainable luxury with exceptional brilliance, certified by leading gemological institutes.'
      : 'Discover handcrafted luxury fine jewellery, rings, earrings, bracelets, and necklaces made with certified gold and precious diamonds at Neirah Jewels.';

  return (
    <div className="min-h-[75vh] bg-white">
      <SEO
        title={seoTitle}
        description={seoDescription}
        type="website"
      />
      {/* ─── Top Category Banner Image (Exact Match: 100% full width, max-h-[360px], object-cover, bg-[#FAF7F2]) ─── */}
      {displayBanner && (
        <div className="w-full relative overflow-hidden bg-[#FAF7F2]">
          {displayBanner.image?.mediaType === 'video' ? (
            <video
              src={displayBanner.image?.url}
              autoPlay
              loop
              muted
              playsInline
              className="w-full h-auto block max-h-[360px] object-cover"
            />
          ) : (
            <img
              src={displayBanner.image?.url}
              className="w-full h-auto block max-h-[360px] object-cover"
              alt={displayBanner.content?.title || category?.name || pageTitle || 'Category Banner'}
            />
          )}
        </div>
      )}

      {/* ─── Category Coupon Code Strip (Styled with active storefront dark header theme) ─── */}
      {currentCoupon && (
        <div
          style={{
            backgroundColor: 'var(--storefront-coupon-bg, var(--storefront-header-bg, #201e1b))',
            color: 'var(--storefront-coupon-text, var(--storefront-header-text, #ffffff))',
          }}
          className="w-full py-1.5 sm:py-2 px-4 border-t border-b border-black/10 select-none flex items-center justify-center transition-colors"
        >
          <div className="max-w-7xl w-full mx-auto flex items-center justify-center">
            {(() => {
              const { code, discountPhrase } = getCouponDisplayText(currentCoupon);
              return (
                <button
                  type="button"
                  onClick={() => handleCopyCoupon(code)}
                  className="group inline-flex items-center justify-center gap-2 text-[11px] sm:text-xs md:text-[13px] tracking-wider uppercase font-medium text-current hover:opacity-95 transition-all cursor-pointer focus:outline-none leading-tight"
                  title="Click to copy coupon code"
                >
                  <HiOutlineTag className="w-3.5 h-3.5 sm:w-4 sm:h-4 opacity-90 group-hover:scale-110 transition-transform flex-shrink-0" />
                  <span className="truncate">
                    USE CODE <strong className="font-bold underline decoration-dotted underline-offset-2 tracking-widest opacity-100 group-hover:opacity-100 transition-opacity">'{code}'</strong> {discountPhrase}
                  </span>
                  {copiedCouponCode === code && (
                    <span className="inline-flex items-center gap-0.5 text-[10px] font-semibold bg-white/20 px-2 py-0.5 rounded-full ml-2 normal-case tracking-normal flex-shrink-0 shadow-xs border border-white/25">
                      <HiOutlineCheck className="w-3 h-3" /> Copied!
                    </span>
                  )}
                </button>
              );
            })()}
          </div>
        </div>
      )}

      <div className="px-4 pb-16 pt-4 sm:px-8 lg:px-12">
        <div className="mx-auto max-w-[1440px]">
        {/* ─── Category Header Title (Centered) ─── */}
        <div className="py-2.5 sm:py-3 text-center">
          <h1 className="font-serif text-xl sm:text-2xl lg:text-[26px] text-stone-900 tracking-tight capitalize">
            {pageTitle}
          </h1>
          <LuxuryDivider
            lineWidth="w-10 sm:w-16"
            starSize="w-2.5 h-2.5 sm:w-3 sm:h-3"
            className="mt-1.5 sm:mt-2"
          />
        </div>

        {/* ─── Top Meta Toolbar (Results Count & Sort) ─── */}
        <div className="flex items-center justify-between py-3.5 mb-6 border-b border-stone-200/80">
          <div className="flex items-center gap-1.5 text-xs sm:text-[13px] text-stone-600 font-medium">
            <span>
              {displayCount} {isDiamondCategory ? (displayCount === 1 ? 'diamond' : 'diamonds') : (displayCount === 1 ? 'product' : 'products')} found
            </span>
            <span
              title="Count of items matching current selection"
              className="inline-flex items-center justify-center text-stone-400 hover:text-stone-700 cursor-help transition-colors"
            >
              <HiOutlineInformationCircle className="w-4 h-4" />
            </span>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setMobileFilters(!mobileFilters)}
              className="flex items-center gap-1.5 rounded border border-stone-200 px-3 py-1.5 text-xs font-semibold text-stone-700 lg:hidden cursor-pointer"
            >
              <HiOutlineAdjustments className="w-3.5 h-3.5" />
              <span>Filters</span>
            </button>

            <span className="hidden sm:inline-block text-[11px] font-bold uppercase tracking-wider text-stone-500">
              SORT BY:
            </span>
            <Dropdown
              value={sort}
              onChange={(val) => updateFilters({ sort: val })}
              options={
                isDiamondCategory
                  ? [
                      { value: 'newest', label: 'Newest' },
                      { value: 'price-low', label: 'Price: Low to High' },
                      { value: 'price-high', label: 'Price: High to Low' },
                      { value: 'carat-asc', label: 'Carat: Low to High' },
                      { value: 'carat-desc', label: 'Carat: High to Low' },
                    ]
                  : [
                      { value: 'newest', label: 'Newest' },
                      { value: 'price-low', label: 'Price: Low to High' },
                      { value: 'price-high', label: 'Price: High to Low' },
                    ]
              }
              size="sm"
              className="w-44 sm:w-48"
              menuClassName="z-[40] w-48 sm:w-52 right-0 left-auto"
            />
          </div>
        </div>

        {/* ─── Main Grid: Left Filters & Right Products ─── */}
        <div className="grid items-start gap-8 lg:grid-cols-[260px_minmax(0,1fr)] xl:gap-12">
          {/* Left Filter Sidebar */}
          <div className={`${mobileFilters ? 'block' : 'hidden'} lg:block`}>
            <FilterSidebar
              filters={dynamicFilters}
              loading={loadingFilters}
              params={params}
              onFilterChange={(key, value, isCategory) => {
                if (isCategory) {
                  updateFilters({ category: value, menuItem: '', promoBanner: '' });
                } else {
                  updateFilters({ [key]: value });
                }
              }}
              onPriceChange={(min, max) => {
                if (min || max) {
                  updateFilters({ minPrice: min, maxPrice: max, sort: 'price-low' });
                } else {
                  updateFilters({ minPrice: '', maxPrice: '', ...(params.get('sort') === 'price-low' ? { sort: 'newest' } : {}) });
                }
              }}
              onClearAll={() => setParams({})}
              filtersActive={filtersActive}
              categories={categories}
              currentCategoryParam={categoryParam}
            />
          </div>

          {/* Right Product Grid Column */}
          <section aria-label="Jewellery catalogue" aria-busy={isInitialLoading || isRefetching} className="min-w-0">
            {/* Active Filter Chips */}
            {activeChips.length > 0 && (
              <div className="mb-6 flex flex-wrap items-center gap-2">
                {activeChips.map(({ label, onRemove }) => (
                  <button
                    key={label}
                    type="button"
                    onClick={onRemove}
                    className="inline-flex items-center gap-1.5 rounded-full border border-stone-200 bg-white px-3 py-1 text-xs text-stone-700 hover:border-stone-400 transition-colors cursor-pointer"
                    aria-label={`Remove ${label} filter`}
                  >
                    <span>{label}</span>
                    <HiOutlineX className="w-3.5 h-3.5 text-stone-400 hover:text-stone-700" />
                  </button>
                ))}
              </div>
            )}

            {/* Products Grid / Skeletons / Empty */}
            {isInitialLoading && products.length === 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-x-2 sm:gap-x-3.5 gap-y-3 sm:gap-y-6">
                {Array.from({ length: 8 }, (_, index) => (
                  <div key={index} className="animate-pulse rounded-lg sm:rounded-xl border border-gray-100 bg-white p-2 sm:p-2.5">
                    <div className="aspect-square rounded-md sm:rounded-lg bg-stone-100" />
                    <div className="mt-2.5 h-3 w-4/5 bg-stone-100 rounded" />
                    <div className="mt-1.5 h-3 w-1/2 bg-stone-100 rounded" />
                    <div className="mt-2.5 h-3.5 w-1/3 bg-stone-100 rounded" />
                  </div>
                ))}
              </div>
            ) : error && products.length === 0 ? (
              <div role="alert" className="py-20 text-center">
                <p className="text-sm text-stone-600">{error}</p>
                <button
                  onClick={() => setRetry((v) => v + 1)}
                  className="mt-5 rounded border border-stone-300 px-5 py-2 text-sm hover:bg-stone-50 cursor-pointer"
                >
                  Try again
                </button>
              </div>
            ) : sortedDisplayedProducts.length ? (
              <div className="relative">
                {/* Subtle luxury shimmer line when updating filters / category */}
                {isRefetching && (
                  <div className="absolute -top-3 left-0 right-0 h-0.5 overflow-hidden z-20 rounded-full bg-stone-100">
                    <div className="h-full w-full bg-gradient-to-r from-transparent via-[#8b6f4e] to-transparent animate-pulse" />
                  </div>
                )}
                <div
                  className={`grid grid-cols-2 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-x-2 sm:gap-x-3.5 gap-y-3 sm:gap-y-6 transition-all duration-300 ${
                    isRefetching ? 'opacity-65 pointer-events-none' : 'opacity-100'
                  }`}
                >
                  {sortedDisplayedProducts.map((product) => (
                    <ProductCard key={product._id || product.id} product={product} />
                  ))}
                </div>
              </div>
            ) : (
              <div className="flex min-h-[420px] flex-col items-center justify-center text-center">
                <h2 className="text-xl text-stone-800 font-serif">
                  {isDiamondCategory ? 'No diamonds available' : 'No products available'}
                </h2>
                {filtersActive && (
                  <button
                    onClick={() => setParams({})}
                    className="mt-6 inline-flex items-center gap-2 rounded-lg border border-[#d6c7b2] hover:border-[#8b6f4e] px-4 py-2 text-xs sm:text-[13px] font-medium text-[#8b6f4e] bg-white hover:bg-[#FAF7F2] transition-all duration-200 shadow-2xs hover:shadow-xs active:scale-95 cursor-pointer"
                  >
                    <HiOutlineTrash className="w-4 h-4 text-[#8b6f4e]" />
                    <span>Clear All Filters</span>
                  </button>
                )}
              </div>
            )}

            {/* Pagination Controls */}
            {!isInitialLoading && !error && pagination.totalDocs > 0 && (
              <nav
                aria-label="Product pagination"
                className={`mt-12 sm:mt-16 pt-6 sm:pt-8 border-t border-stone-200/80 flex flex-col items-center gap-4 transition-opacity duration-200 ${
                  isRefetching ? 'opacity-50 pointer-events-none' : 'opacity-100'
                }`}
              >
                {/* Desktop View (Single unified row) */}
                <div className="hidden sm:flex items-center justify-between w-full">
                  {/* Product count summary */}
                  <div className="text-xs sm:text-sm text-stone-500 font-medium">
                    Showing{' '}
                    <span className="font-semibold text-stone-800">
                      {Math.min((page - 1) * limit + 1, pagination.totalDocs)}
                    </span>
                    {' '}–{' '}
                    <span className="font-semibold text-stone-800">
                      {Math.min(page * limit, pagination.totalDocs)}
                    </span>
                    {' '}of{' '}
                    <span className="font-semibold text-stone-800">
                      {pagination.totalDocs}
                    </span>
                    {' '}{isDiamondCategory ? (pagination.totalDocs === 1 ? 'diamond' : 'diamonds') : (pagination.totalDocs === 1 ? 'product' : 'products')}
                  </div>

                  {/* Page Buttons */}
                  <div className="flex items-center gap-1.5">
                    {/* Previous Page Button */}
                    <button
                      type="button"
                      disabled={page <= 1}
                      onClick={() => goToPage(page - 1)}
                      className="w-9 h-9 flex items-center justify-center rounded-lg border border-stone-200 bg-white text-stone-700 hover:bg-[#FAF7F2] hover:border-[#8b6f4e] hover:text-[#8b6f4e] disabled:opacity-40 disabled:hover:bg-white disabled:hover:border-stone-200 disabled:hover:text-stone-700 disabled:cursor-not-allowed transition-all duration-150 cursor-pointer shadow-2xs"
                      aria-label="Previous page"
                      title="Previous page"
                    >
                      <HiOutlineChevronLeft className="w-4 h-4" />
                    </button>

                    {/* Numbered Page Buttons */}
